def make_extended_notes(table,gunshi,responses,cite):
    notes=[]
    def p(*texts):return ''.join('<p>'+t+'</p>' for t in texts)
    def add(slug,field,title,deck,finding,parts,sources,group,question,answer):
        assert len(parts)==5 and len(set(sources))==len(sources)
        body=''.join(f'<section id="{key}"><h2>{heading}</h2>{text}</section>' for key,(heading,text) in zip(['question','evidence','analysis','alternatives','test'],parts))
        body+=f'<aside class="research-exercise"><p class="eyebrow">READ &amp; THINK</p><h3>{question}</h3><details><summary>考え方を読む</summary><p>{answer}</p></details></aside>'
        notes.append(dict(slug=slug,field=field,title=title,deck=deck,finding=finding,body=body,sources=sources,group=group))

    # Entries below are selected by independently evidenced questions, never by a count quota.
    add('oyaku-oyako-and-kin-groups','親族集団語・言語地理','「オヤク・オヤコ・チルイ・イッケ・マキ」は、同じ親類か',
    '浜名湖の東西と水窪西浦の記述を比べ、親類の一語訳に隠れる分類の違いを読む。',
    '親類を表す語の違いには、地域ごとの語形の交代だけでなく、血のつながり・身内・一族という意味の分け方もあります。1969年に寄せられた報告は、その両方を区別する手がかりです。',[
    ('「親類」の訳をそろえる前に',p('郡誌で親類と説明された語と、後年の研究で集団の範囲まで説明された語を並べるとき、同じ訳語だから同じ集団を指すと決めることはできません。個人からたどる親戚、ある家に連なる人々、婚姻で結ばれた人々という範囲の違いが、短い日本語訳では隠れるからです。','ここでは一人の父や兄を表す個人親族語ではなく、複数の人々のまとまりを表す親族集団語を扱います。家系図の線を描くだけでなく、当事者がどこまでを一つのまとまりと捉えるかが研究の対象になります。')),
    ('三種類の証拠を並べる',gunshi('おやく')+p('渡辺（1970）58頁は、山口幸洋の回答として、新居の子ども時代のオヤコ、舞阪のオヤクを述べ、水窪西浦ではチルイ・イッケ・マキなどを区別しています。新居の記述は回想を含み、浜名湖周辺の広い分布の説明には先行調査への言及もあります。'+cite('kin1970regional','渡辺1970・58頁'))+table(['資料内の場所','挙げられた語','資料での意味・条件'],[['袋井町／郡誌1921','おやく','親類という対応語'],['新居・舞阪／1970年報告','オヤコ・オヤク','回想・報告・先行調査への言及を含む'],['水窪西浦／同報告','チルイ・イッケ・マキ等','血縁・身内・一族という説明の差']], '年代と記述の種類を区別した照合')),
    ('地図の違いと、意味の違い',p('浜名湖の東西で似た意味を別形で表すという比較と、西浦で複数語が意味の違いを持つという比較は、同じ種類の図にはなりません。前者は語形の地域分布、後者は一地域の語彙体系の問題です。地図へ一語だけを塗り分けると、同じ場所で複数語を使い分ける仕組みが落ちてしまいます。','西浦の説明では、チルイには血のつながり、イッケには身内という含みが示され、マキ・シンルイマキは親類や一族に関わる形として述べられます。これらをすべて同義語の一覧に置くより、誰を含み、どんな場面で選ぶかという問いを残す方が記述に忠実です。','同じ家を中心にした集団でも、話し手が変われば身内の範囲が動く可能性があります。語形の分布と、指示対象の範囲を別の欄で記録することで、地理学的な比較と社会関係の比較を接続できます。')),
    ('「今では」と書かれた時点を固定する',p('1970年の報告にある新旧の説明を、現在の2026年の状況へそのまま移してはいけません。調査回答の時点、回想対象の時点、採録元の調査時点が一つの段落に共存しています。報告書の刊行年は、全用例の発話年でも語の成立年でもありません。','また、資料の「ないようだ」という推測の強さを、地域全体に絶対存在しないという断定へ変えません。郡誌の袋井町一行と、西浦の報告は異なる地域・方法の資料です。比較から問いは作れますが、一つの語がもう一つへ変化した歴史まで自動的に復元できるわけではありません。')),
    ('同じ関係図で、含まれる人を確かめる',p('検証には、本人を基準にした親戚の図と、家を中心にしたつながりの図を別々に用意し、どの範囲を各語で呼ぶか確かめる方法があります。実名の公開は不要です。調査用の匿名の図に、血縁・婚姻・同居・儀礼上の付き合いなどの関係を分けて記録できます。','学習では、表の語を「場所の違い」と「意味の違い」の二軸に置き直してみてください。同じ親類という訳語の背後にある区別を読むことで、語数を覚える学習から、地域社会の分類の仕組みを理解する学習へ進めます。'))],
    ['gunshi','kin1970regional'],'kinship','オヤクとマキを同じ「親類」に訳せば、同じ範囲の人を指す？','訳が同じでも、個人・家・血縁などの分類軸や含まれる範囲は異なりえます。地域と時点をそろえ、実際に含む人々を比較します。')

    add('parent-spouse-and-household-role','親族語彙・多義性','「オットー・オトッサ・オッカー」は、親か、配偶者か、家の役割か',
    '水窪と遠州方言集の採録を読み、父・母だけに訳し切れない語の意味の重なりを考える。',
    '同じ人を父・配偶者・家の成員として捉えることと、一つの語が複数の意味を持つことは関係します。誰から見た関係かを添えると、親族語の多義性を具体的に説明できます。',[
    ('一人の人物に、複数の関係が重なる',p('ある人は子どもから見れば父であり、別の人から見れば配偶者です。家の仕事や暮らしを取りまとめる人として語られる場合もあります。同じ人物を指せることは、父・夫・世帯の役割という概念が同じであることを意味しません。','親族語を一対一の置換辞書にする前に、語が表す関係と、使用者がその人をどの位置から捉えるかを分けます。この区別は、翻訳だけでなく、過去の資料から家族の構造を説明する際にも必要になります。')),
    ('国語研報告が並べた遠州の記録',table(['報告書内の形','47頁の対応','採録元のラベル'],[['オットー','父・亭主','磐田郡水窪町における語彙整理'],['オトッサ','父親・年配の世帯を持った男子','遠州方言集'],['オッカー','主婦','水窪方言の基礎調査']], '渡辺1979の文献採録から、該当部分を整理')+p('これは渡辺（1979）の公開本文を介した確認です。元の各方言集を今回直接読み直したという意味ではありません。また同じ静岡県欄には駿河岡部の例もありますが、その例を遠州の語彙へ混ぜていません。'+cite('kin1979parents','渡辺1979・47頁'))),
    ('関係の意味と、役割の意味を分ける',p('父は誰かの子どもとの関係を必要とし、亭主という説明は配偶関係を、主婦という説明は家の中の社会的役割を示します。資料上これらが近く置かれていても、現代の家族の役割を一律に固定するための分類ではありません。当時の採録者がどの観点を訳語に選んだかを読むための区別です。','オトッサの対応にある世帯を持った年配の男性という説明は、血縁上の父だけに語が閉じていない可能性を示します。ここでは、親族語が家族外の人や生活段階へ広がるという問題を、単なる親しさの言い換えとは別に考えられます。','一方、オッカーが主婦と整理されている一行だけから、母を指す用法が必ずあるとも絶対ないとも決められません。資料が明示した意味をまず保持し、別の意味があるかという調査項目を追加するのが適切です。')),
    ('訳語の違いは、採録方法の違いでも生じる',p('ある方言集が家族を尋ね、別の方言集が暮らしの人物名を集めたなら、同じような形でも採られる意味の範囲が違います。訳語の数だけを数えて、ある地域の家族関係が複雑だと結論することはできません。編者の目的や項目の作り方を比較に含めます。','また、見出しの長音や促音を整えて一語に統合すると、元の採録の違いが消えます。現代表記で検索する欄を作る場合も原表記を残し、別資料のオトッサと郡誌のおつつあを、形が似るだけで同一語・同義語にしないことが必要です。')),
    ('関係を入れ替えて読める表を作る',p('記録票には、語形、指した相手、話し手との関係、第三者の有無、資料の対応語を分けて置きます。父を話題にする文と、地域の大人を話題にする文を集める場合も、今回の表が実際の会話例であるかのように例文を補作しません。','学習では父・配偶者・家の役割を別の円として描き、同じ人が複数に属しうることを確かめます。その上で資料の語を重ねれば、親族語を単語帳としてだけ読むと見えにくかった意味の構造が分かります。'))],
    ['kin1979parents'],'kinship','オットーが父と亭主の両方に対応するなら、父と夫は同じ意味？','同じ人を異なる関係から捉えた用法が重なっています。語の多義性と、親族関係そのものの同一性を区別します。')

    add('kinship-viewpoint-in-conversation','呼称・会話参加者','夫婦で「お父さん」と呼ぶとき、誰の視点で話しているか',
    '子どもの同席と呼び方の変化を先行研究から読み、遠州の家族語を調べるための視点を整える。',
    '呼び方は話し手と相手だけで決まるとは限りません。その場の子どもや孫の視点が取り込まれることがあり、親族関係と会話の参加者を分けると仕組みが見えてきます。',[
    ('話し手の家系図だけでは説明できない呼び方',p('配偶者を父や母の語で呼ぶ現象を、自分の父母を呼んでいると解釈すると関係を取り違えます。子どもから見た関係が会話の中へ取り込まれている場合、話し手の実際の親族関係と、選ばれた呼称の基準となる人が違うからです。','このノートは遠州の全家庭で同じ呼び方をするという実態報告ではありません。先行する家族呼称の研究で、何を観察すればこうした現象を説明できるかを読み、遠州の資料を増やす際の観察単位を具体化します。')),
    ('福島北部の家族研究が示す比較の視点',p('渡辺（1970）は、福島北部を中心とする家族の呼称を世代や配偶者の組合せで整理しています。第11表と分析では、子どもが生まれる前後や、子ども・孫がその場にいるかにより、夫婦間の呼称の選択が変わる事例を述べています。これは特定の家族についての分析です。'+cite('kin1970viewpoint','渡辺1970・163–166頁、第11表'))+table(['区別する人・条件','記録する理由'],[['話し手','誰が呼び方を選んだか'],['呼ばれる人','親族関係上は誰か'],['視点の基準となる子・孫','父・母・祖父母という関係の基点'],['同席者と時期','家族構成・会話の場による選択の差']], '先行研究をもとに編集部が整理した観察の枠')),
    ('「子どもの立場で呼ぶ」と「子どもに話す」は違う',p('子どもを基準とする呼び方でも、直接の聞き手が子どもとは限りません。配偶者へ話しているが、子どものいる場に合う名前を使う場合と、子どもへその人のことを話す場合を分けます。誰に向けた発話かと、誰から見た関係を表すかという二つの情報が必要です。','もう一つの区別は、一時的な選択と日常の習慣です。子どものいる場面だけで選ぶのか、その呼称が定着して二人だけの場面でも続くのかでは、説明が変わります。呼び方を一回聞いただけで家庭の恒常的な呼称体系を決めないための視点です。','遠州のオットーのように父と亭主の対応が同じ形に現れる資料と比較する際も、意味の重なりだけで、この会話上の仕組みが実際に働いていたと証明できるわけではありません。語彙資料が示す可能性と、会話資料で確認する使い分けを接続する段階を明示します。')),
    ('世代の違いと、家族の変化を混ぜない',p('若い夫婦と高齢の夫婦の呼び方が異なっていても、それが地域全体の言語変化とは限りません。子どもの誕生、孫との同居、長い使用習慣という家族の生活史が違うからです。同じ年齢層だけを比べても、家族構成を見なければ条件はそろいません。','また、過去の一家庭で見られた夫と妻の非対称を、性別による普遍的な規則として教えないことも大切です。先行研究の対象と結論の範囲を保持し、現在の多様な家族に当てはめるときには別の実証を要します。')),
    ('一場面を、四者の配置で読む',p('教材としては、匿名の図に話し手・相手・同席者・呼称の基準となる人を配置します。「お父さん」という一語を見て即座に話し手との関係を決めず、誰から見た父かを確かめる練習になります。これは編集部作成の分析図式で、採録された遠州の発話の再現ではありません。','実際の記録では前後の会話や、その場にいた人の情報が役立ちます。家族の同意と公開範囲を分けながら、年代・場面・話者の関係を残せば、親族語彙の辞書を会話の研究へつなげられます。'))],
    ['kin1970viewpoint','kin1979parents'],'kinship','話し手が相手を「お父さん」と呼べば、相手は話し手の父？','会話に参加する子どもなどの視点で呼ぶ可能性があります。話し手の関係、聞き手、呼称の基準となる人を分けて読みます。')

    add('ura-onshi-waira','人称表現・相手との関係','「うら・おんし・わいら」を、一人称・二人称だけで訳せるか',
    '郡誌の記録地と対応語を保ち、話し手・相手・人数・評価という別々の情報を読む。',
    '人称を指す語は、同じ地域の一つの体系として集められたとは限りません。原注の意味、人数、会話の相手に対する態度は、異なる証拠から確かめる必要があります。',[
    ('人を指す言葉にも、異なる分類がある',p('人の呼び方には、個人名、親族語、役職名のほか、話し手や聞き手を指す人称表現があります。これらは辞書上で同じ人に訳せても、会話の中で働く位置が違います。親族関係を言い表すことと、今ここにいる相手を指すことを分けて考えます。','「私」「おまえ」「あなたがた」といった訳語を置くと分かりやすくなりますが、訳語側の丁寧さや人数の区別を原資料へ無条件に持ち込む危険もあります。原資料の対応と、現代の説明のための訳を別に示す必要があります。')),
    ('三語は、三つの異なる記録地にある',gunshi('うら','おんし','わいら')+p('うらは於保村、おんしは佐久間村、わいらは福島村の記録です。郡誌の原注には、それぞれ己等、お主の転、なんぢらという情報があります。原注にある語源の説明は、当該資料の説明として保持し、別の歴史資料まで確認した語源の確定とは扱いません。'+cite('gunshi','磐田郡誌・1244、1253頁'))),
    ('人称・数・待遇を三つの軸で考える',table(['軸','問い','必要な証拠'],[['人称','話し手か、相手か、第三者か','文中で誰を指しているか'],['数','一人か、複数か、周囲の仲間を含むか','指された人の範囲と用例'],['待遇・態度','親しさ・上下・対立などを示すか','前後の会話と当事者の説明']], '編集部による人称表現の分析枠')+p('うらの原注に複数を思わせる文字があることと、個々の使用で必ず複数人を指すことは同じではありません。訳語の文字面だけで現代の単複の使い分けを断定せず、資料内の説明の強さを保ちます。','同じように、おんしという形を見ただけで、いつでも親しい、あるいはいつでも失礼だと決めることはできません。相手の年齢、親疎、発話の行為、声の調子が分からない語彙欄は、語の対応を示す証拠として読みます。')),
    ('離れた三語を、一つの活用表へしない',p('地域の違う語を一枚に並べることは比較には役立ちますが、同じ話者が自分をうらと呼び、相手をおんし、その複数をわいらと言った証拠にはなりません。場所の異なる採録を一つの自然な会話へ組み合わせると、資料にない体系を作ってしまいます。','発音についても、仮名からアクセントの型や具体的な母音の長さまで補いません。文字資料では対応語・地域・原注を確かめ、音声資料が得られた段階で、形の対応や発話の違いを検証します。')),
    ('使い方の教材へ進むための条件',p('今後の用例には、発話者と相手の匿名ID、場所の公開範囲、指している人数、発話の目的、前後の応答を添えると有効です。自己紹介、親しい相手への依頼、複数の相手への呼びかけなどを分ければ、人称という分類と具体的な会話の機能を比較できます。','学習では、各語のカードに地域と原注を残し、「この語を使ってよい場面が分かった」と「資料でこの対応を確認した」を分けて説明してみてください。ことばを広める際も、原資料にない対人上の評価を固定しない姿勢が必要です。'))],
    ['gunshi'],'kinship','三語が郡誌に載るなら、その三語を一人の会話に並べて再現できる？','記録地も用例の条件も異なります。同じ話者が併用した証拠が得られるまでは、一つの会話体系として再現しません。')

    add('historical-person-labels','語彙と社会評価','人を呼ぶ語に、当時の評価や身分観をどう読むか',
    'おだい・なまかあ・やごめ等の分類を比べ、人の状態と採録者の評価を切り分ける。',
    '歴史資料には、関係や生活段階を表す語と、人物への評価を表す語が混在します。記録に残す価値と、現代の人への呼びかけとして勧めることは別に判断します。',[
    ('人の名前ではなく、どんなカテゴリーなのか',p('人を指す語をすべて親族語やあだ名の箱に入れると、何を分類しているのかが見えなくなります。財産の状態を示す対応、婚姻に関わる状態、仕事ぶりへの評価は異なる分類です。呼称を読むときには、まずその語が人の何を取り上げたかを明確にします。','歴史的な記述には、現在は人へ向けることを勧めない評価語も含まれます。ここでは当時の資料の分類を調べる対象とし、他人を品定めするための言い回し集や、実際の人物への例文は作りません。')),
    ('記録上の異なる意味の軸',gunshi('おだい','なまかあ','やごめ')+p('おだいは財産家、なまかあは怠け者、やごめは寡婦という対応を持ちます。記録地と項目は別々です。一つの集落で人々を三段階に分けた制度の表ではありません。'+cite('gunshi','磐田郡誌・1244、1250、1252頁'))+table(['比較する内容','資料からまず読むもの','別の調査を要するもの'],[['経済的な位置','財産家という対応語','どの程度の財産を基準としたか'],['人物への評価','怠け者という価値判断','誰がどの行動をそう評したか'],['生活上の状態','寡婦という対応語','その人の権利・役割・呼ばれ方']], '一律の人物分類へまとめないための表')),
    ('評価語は、行動をそのまま測った数値ではない',p('怠け者という語があることは、当人の働く時間が測定されていることを意味しません。話し手の期待や人間関係によって評価されることがあり、どんな作業をどれだけ行ったかという事実の記録とは性質が違います。語の意味と人物の実像を結び付けるには、発話の場面が必要です。','財産家の対応語がある場合も、村の階層を示す客観的な戸数表には置き換えられません。語が区別する社会的位置と、歴史研究が土地・資産・職業の記録から測る位置を分けます。その対応を検証することは可能ですが、語があるだけで制度の全体が分かったとは言えません。','やごめのような生活段階に関わる語は、本人をどの場面で実際に呼んだかという問題と、誰かについて説明する語彙があったという問題を区別します。人物の語を、すべて本人へ直接呼びかける形として提示しないことが大切です。')),
    ('過去の説明を、そのまま現代の規範にしない',p('同じ資料には出自や身体に関する歴史的な呼称も収められています。資料の語を消して見えなくするのでも、親しみのある郷土語として無条件に勧めるのでもなく、原表記・出典・歴史的文脈と、現代での扱いを分けて記載します。','ただし、原資料に現代の説明を加えた場合は、それを原注と混同させてはいけません。引用、現代語による意味整理、編集部の利用上の説明を明示して、どの部分が1921年の記述なのかをたどれる状態にします。')),
    ('語義・評価者・対象者を別々に読む',p('研究の記録には、語の意味、評価した人、評価された行為、相手との関係、資料の記述者を別欄で残します。現地で聞く場合も、語を知るかという質問と、その語で誰かを呼びたいかという質問は同じではありません。','学習では、資料の一行から人物について断定できることを最小限にして書き出します。「この対応語がある」は確認できますが、「地域の人は皆その分類で考えた」は確認できません。人の呼び方を社会史へつなぐには、この証拠の距離を明確にすることが必要です。'))],
    ['gunshi'],'kinship','人物評価の語が記録されていれば、当時の全住民が同じ価値観だった？','採録された語と、全住民の意識・行動は別の資料です。話者・場面・記録者の条件を含めて検討します。')

    add('house-name-form-and-origin','屋号研究・歴史資料','人名に見える屋号は、本当に昔の当主名から来たのか',
    '掛塚の屋号の読解を、新潟の屋号研究と比較し、形・由来・命名時期を別々に確かめる。',
    '人名のような形であることと、実在した人物の名に由来することは別です。屋号の意味分類には、聞き取りだけでなく、いつの文書に何の名として現れるかという照合が必要になります。',[
    ('形による分類は、由来の証明ではない',p('屋号を見て、職業らしい、人名らしい、地形らしいと分類することは、資料を整理する入口になります。しかし、その見た目は命名の経緯をそのまま示すとは限りません。人名に似た要素を後から付けた場合や、別の意味の形が人名に見える場合も、調査では区別する必要があります。','既存ノートで扱った掛塚のつたやは、図書館資料に屋号として示された例です。その由来が説明されていない部分を、名前の印象から補うことはできません。ここでは別地域の実証研究から、どんな史料をそろえると由来を比較できるかを検討します。')),
    ('新潟の研究が区別した二つの「人名らしさ」',p('松村・竹本（2024）は新潟県上越市不動地区の屋号を分析し、人名に由来する屋号と、人名らしい形を持つ屋号の成立を区別しています。集落差、成立時期、建物の記録などを合わせる研究であり、遠州の屋号の起源を調べた論文ではありません。'+cite('yago2024','松村・竹本2024・背景、要旨'))+table(['調査の層','確かめる問い','証拠の例'],[['形','何の名前に見えるか','原表記・地域での読み'],['由来','何にちなんで名付けたか','来歴の説明・当時の文書'],['時期','いつからその名があるか','年代の分かる台帳・取引記録'],['対象','家・屋敷・人・事業のどれか','資料内の用法と位置']], '屋号の形と命名史を分ける枠組み')),
    ('地域の中の変化を、同じ文字列から追う',p('同じ屋号が続いていても、家の所在地、建物、事業の内容、当主は変化しえます。文書に同じ名があることを継続の一証拠としつつ、何が続いたかを個別に述べる必要があります。名が同じことと、同じ血縁や職業が続くことを同一視しません。','屋号を人・土地・系譜・職業のような観点で整理する場合も、分類項目は研究者が置いた分析の枠です。当事者が同じ区分で意識していたことを確かめるには、説明の言葉や実際の呼び分けを調べます。一つの屋号が複数の観点へまたがることも残します。','掛塚の商家のような取引と結び付く例を扱うときは、宛名、看板、印、口頭での呼び方を別にします。文書の署名にある名が、そのまま隣人が本人を呼ぶ形だったとは限らないためです。')),
    ('同姓だから生まれた、という説明を急がない',p('同じ苗字の家が多いから屋号が必要になった、という説明は理解しやすいものの、個々の地域で成立時期や具体的な命名の資料を照合する必要があります。実際に区別に役立つという現在の機能と、そのために最初に名付けたという起源は別の問いです。','また、ある地方の研究で確認された割合や由来を遠州へ移すことはできません。比較研究は、遠州の未確認部分を埋める代用品ではなく、こちらの資料でどこを確かめるべきかを明確にするために使います。')),
    ('年代を付けた名前の照合を行う',p('比較用の記録では、原表記、読みの出所、年代、場所、指す対象、由来を述べた資料を列にします。聞き取りで得た由来なら、誰がいつそう説明したかを残し、同時代の命名記録とは区別します。個人の現住所と家族の詳細を無断で公開する必要はありません。','学習では、「人名に見える」「人名から来たと伝えられる」「当時の記録で人名との対応を確認した」の三枚を分けてみてください。確からしさの異なる情報を一つの語源説明へ丸めず、名前が地域の記憶を担う仕組みを検討できます。'))],
    ['yago2024','ryuyo2025'],'kinship','屋号の末尾が人名のようなら、昔の当主名と確定できる？','形の似方だけでは由来は決まりません。年代、実際の人名、命名の説明、家や建物の記録を照合します。')

    add('yuto-market-house-names','生業・市場のコミュニケーション','雄踏市場では、屋号が紙札から声へ移る',
    '県の市場取材を読み、書く・渡す・読み上げるという取引の順序の中で、人の呼び方を考える。',
    '市場の屋号は、家の来歴を示すだけでなく、取引主体を識別する働きを持ちます。紙札に書かれた印と読み上げられる名を対応させると、仕事の中で名前が機能する過程を説明できます。',[
    ('屋号を、辞書の見出しから取引の行為へ戻す',p('屋号は誰の名かという問いに加え、誰が、いつ、何のために使う名かという問いがあります。市場では買い手を識別し、申し出た金額と対応させ、取引の結果を伝えるという複数の場面が連続します。名前は単独で置かれるのでなく、その一連の行為の中で働きます。','このノートでは、実際の取材記事に記述された紙札と競りの手順を扱います。編集部が新たに競りを録音したり、方言の掛け声を採録したりした資料ではありません。確認できた行為から、名前の使われ方を読みます。')),
    ('2024年の雄踏市場の取材記述',p('県のしずおか食の情報センターの記事は、仲買人が屋号の印のある紙札に希望額を書き、競り人へ渡し、最高額を付けた仲買人の屋号と金額が読み上げられる様子を紹介しています。記事に記述されたこの対応が、分析の起点です。'+cite('market2024','静岡県2024・雄踏市場の段落'))+table(['段階','用いられるもの','名前の働き'],[['申し出る','屋号の印と金額のある紙札','買い手と金額を対応させる'],['受け取る','競り人への札の受け渡し','申し出を取引の手順へ組み込む'],['伝える','屋号と金額の読み上げ','落札した主体と結果を知らせる']], '県の取材記述をもとにした編集部の行為分析')),
    ('同じ名が、文字と声で異なる役を担う',p('紙札は後から見返せる記録であり、声はその場の人へ結果を伝えます。両者が同じ取引主体を指すとしても、受け手や時間の性質は異なります。屋号を文字列として保存するだけでは、誰に向けて読み上げられ、どの時点で識別に使われるかが落ちます。','また、この場で識別される主体は、氏名で特定される一人の人物とは限りません。商売の名として継承される屋号なら、名の継続と実際に札を出す担当者の交替を別々に追う必要があります。家・事業・担当者を区別すると、職業上の名と個人名の接点が見えてきます。','市場に共有された知識があれば短い名で相手が分かる可能性がありますが、その知識の範囲や学び方は記事だけでは分かりません。どの名を誰が理解できるか、部外者には何の説明が必要かという問いが、次の実証の対象になります。')),
    ('競りの声を、方言の発音標本へ直結しない',p('印刷された取材記事の発話表記は、音声のすべてを記録したものではありません。数字の言い方、声の高低、速度、繰り返し、相手の応答などを研究するなら、音声・映像とその利用条件が必要です。記事の文字からアクセントや実際の競りの調子を作って再生しません。','また、ここで確認した屋号の役割を、掛塚の歴史的な商家や遠州すべての市場へ一律に移すこともできません。同じ屋号という語でも、史料における対象と行為の条件が異なります。')),
    ('名前・媒体・行為を一組で記録する',p('観察する際は、名の原形に加えて、紙札・看板・口頭のどこに現れたか、取引のどの段階か、誰が誰へ伝えたかを記録します。個々の金額や参加者の非公開情報の収集を目的にするのではなく、公開可能な行為の構造を残す方法です。','学習では三段階の札を順番に並べ、屋号を消すとどの情報の対応が難しくなるか考えてみてください。人の呼び方を語義の一覧から取り出し、地域の仕事を実際に進める仕組みとして読めます。'))],
    ['market2024'],'livelihood','市場の屋号を覚えれば、競りの発音や会話全体も分かったことになる？','屋号の識別機能を記事から読めても、音声の特徴や応答の順序の詳細は別の証拠が必要です。文字・音声・行為を区別します。')
    add('sakuma-forest-transport','生業語彙・林業と運搬','「キンマ・ガンリキ」は、山から川への仕事をどう分けるか',
    '佐久間の文化財解説を工程に沿って読み、運ぶ道具・身に着ける道具・仕事の担い手を区別する。',
    '仕事の道具名は、形だけでなく、どの工程で何を実現するかという関係の中にあります。山で材木を下ろす道具と、筏に乗る人の装備を分けると、地域の生業の連鎖が見えてきます。',[
    ('道具を単品で覚える前に、工程を置く',p('木を伐る、山から下ろす、川を流すという作業は、木材を移すという大きな目的の中でも条件が異なります。仕事の語を一列に並べるより、物がどこからどこへ動くときの道具かを整理すると、道具と人の役割を具体的に理解できます。','道具名の語源が分からなくても、その使われる関係は資料から記述できます。名称の成り立ちの推測を先に置くのでなく、資料が説明する対象と工程から読む方法です。')),
    ('佐久間の解説が示す運搬の連なり',p('浜松市の2012年の文化財解説は、キンマを伐採した木材を運び出すそりとして説明し、山から下ろした材を筏に組んで天竜川を流すこと、冬に筏師がガンリキを履いたことを述べています。名称と対象の結び付きは、この解説と写真説明から確認できます。'+cite('sakuma2012','浜松市・佐久間の林業と山村生活の用具'))+table(['資料中の語','対象の種類','作業の中の位置'],[['キンマ','材木を載せるそり','山から運び出す'],['筏','材を組んだ水上のまとまり','川を流して運ぶ'],['筏師','作業の担い手','筏に乗って川を下る'],['ガンリキ','筏師が履く用具','凍る丸太に対応する冬の装備']], '原解説の用途を、工程と対象別に整理')),
    ('「運ぶ道具」と「運ぶ人の道具」の意味の違い',p('キンマは材木を載せる対象で、ガンリキは人が身に着ける対象です。どちらも林業関係の用具として収蔵されても、物を支える働きと身体の作業条件を支える働きが異なります。上位分類が同じことと、道具名が同じ意味を持つことは違います。','また、山と川を別々の産業の箱へ入れるだけでは、材を山から河川へ渡す連鎖が見えにくくなります。道具の語を工程の順序へ置くと、林業と水上運送が結び付く仕事の構造を説明できます。ただしこの構造の説明は、当時の作業中にどのような指示語を使ったかという会話の実証とは別です。','地域の語彙を学ぶ際は、用途を短い共通語に置き換えるだけでなく、運ぶ物・支える場所・使う人・季節という関係を加えることが有効です。名称を知っていても作業を経験していない人が、何を理解し、何をまだ知らないかを明確にできます。')),
    ('一つの解説で、地域全体の使用法を決めない',p('資料は文化財として保存された用具を説明しています。これを佐久間全域のどの時代にも同じ形で使った証拠、現在も同じ作業をする案内として扱いません。収集した用具には採集地・製作時期・使用者・修理の情報があるかを別に確かめる必要があります。','名称の似た道具が他地域にあった場合も、形と用途を照合せずに完全な同義語としません。方言語彙と道具の分布は、語の形、実物、技術の伝播という複数の層を持つからです。')),
    ('仕事の鎖に、資料の位置を付ける',p('記録表には、名称の原表記、物の写真や収蔵番号、用途の説明、工程、使用地域、資料の年代を置きます。どの写真が名称と直接対応しているかを示すと、別のそりや履物の一般画像を当該道具と誤認することを防げます。','学習では、キンマ・筏・筏師・ガンリキを「物を載せる」「物をまとめる」「仕事を担う」「身体に着ける」へ分類してみてください。職業に関する言葉を、道具の一覧から、人と物の関係を読む教材へ変えられます。'))],
    ['sakuma2012'],'livelihood','林業の用具なら、キンマもガンリキも同じ用途の別名？','キンマは材を運ぶそり、ガンリキは筏師が履く用具として説明されています。産業の分類と、対象・用途の分類を分けます。')

    add('yamatsukuri-and-toguwa','生業語彙・山地の農耕','「ヤマツクリ」は山を造ることか――佐久間の焼畑を読む',
    '普通の語の組合せに見える呼称を、地域の用法と傾斜地の作業から読み解く。',
    '言葉を構成する文字の意味と、地域でその語が指す仕事は一致するとは限りません。ヤマツクリを焼畑の呼称として確認し、トウグワという道具名と作業条件を対応させます。',[
    ('文字から作業を想像するだけでは足りない',p('ヤマとツクリという要素を知っていても、それだけでヤマツクリがどんな営みを指すかは決まりません。複合語は、その地域の用法として一つの作業や制度を指すことがあるためです。日常語に見える部分を持つことと、専門的な意味を持たないことは同じではありません。','ここでの問いは、語源を一つに決めることではなく、資料がどの行為へ名称を結び付けているかです。対象となる仕事が分かると、その語と共起する道具や場所の記述も読みやすくなります。')),
    ('佐久間の文化財解説における対応',p('浜松市の解説は、平地の少ない山間地で焼畑をヤマツクリと呼んでいたと説明します。さらに、急傾斜の畑で土が下へ流れないように、谷へ向かってトウグワを使う作業を述べています。これは焼畑の呼称と道具の用途を結び付けた記述です。'+cite('sakuma2012','浜松市2012・佐久間の用具の解説'))+table(['語・情報','資料中での関係','分析で分ける層'],[['ヤマツクリ','焼畑の呼称','作業・生業の名'],['トウグワ','傾斜地を耕す際の用具','物と用途'],['谷へ向かう作業','土が流れることへの対応','地形・身体の向き・動作']], '呼称と作業条件を対応させた表')),
    ('仕事の名前には、行為のまとまりがある',p('焼畑という名称も、特定の一動作だけを表すものではありません。どの作業範囲までをヤマツクリと呼んだかを調べるときには、土地の利用と個々の動作を分けます。耕す道具が説明されているからといって、呼称が耕起だけを意味すると狭めてはいけません。','トウグワについても、鍬という一般的な上位語だけで済ませると、その土地の作業の条件が抜けます。地形、土を動かす方向、姿勢という情報を名称と合わせることで、なぜその道具を選ぶかを考える土台ができます。ただし名前の各音節の由来は、この用途説明から逆算して決めません。','地域の仕事の語彙には、対象物だけでなく、日常的に共有された作業のまとまりが埋め込まれています。一般語で何に当たるかという訳と、実際にどう働いたかという民俗的な記述を併置する意義がここにあります。')),
    ('自然条件と話し方の因果は別に検証する',p('山地の仕事が示されていることは、その地域のすべての語彙や文法が地形から生まれた証拠ではありません。地形が道具の使い方に関係するという説明と、地形が発音や語尾を決めるという説明では必要な証拠が異なります。後者を想像で追加しません。','同じように、ヤマツクリという呼称があることだけで、佐久間の全世帯が同じ時期に焼畑を営んだと結論しません。用具の収集記録や土地利用の資料と照合して、実際の地域・年代・担い手の範囲を記述します。')),
    ('行為を小さく分け、呼称の範囲を確かめる',p('調べる際には、土地を用意する、播く、育てる、収穫するという分析用の区分と、当事者が仕事を区切る名称を別欄にします。編集部の区分を当時の用語として書き足さず、資料に現れた語の範囲を確認します。','学習では、ヤマツクリの文字通りの想像と、資料で説明された対応を二列に書いてみてください。知っている語の組合せに見える方言ほど、現地の対象との結び付きを確かめる必要があることが分かります。'))],
    ['sakuma2012'],'livelihood','ヤマツクリの文字だけから、植林を指すと決められる？','この佐久間の資料では焼畑の呼称として説明されています。語の構成要素からの連想より、出典に示された用法を優先します。')

    add('hamanako-gear-and-fishing-method','生業語彙・漁具と漁法','「うげ・はぜかご・囲目網・はえまわし網」を、何で分類するか',
    '実物・捕り方・対象の魚という三つの軸から、浜名湖の仕事の言葉を読む。',
    '漁具の名と漁法の名は近く使われますが、物・行為・漁獲対象という違う情報を含みます。名称の似方だけで統合せず、原資料の用途説明と対応させると分類が見えてきます。',[
    ('網の名前と、網を使う仕事の名前',p('ある網の名が、その網を使う漁法も指す場合、辞書に物の名か行為の名かというどちらか一つを付けるだけでは不十分です。仕事の現場では、道具、仕掛け、操業の一まとまりの間で呼称が移ることがあるためです。資料が何を説明しているかを先に見ます。','魚を捕る道具という大分類の下でも、誘い入れる、囲い込む、網に掛けるといった仕組みは異なります。名称と仕組みを結び付けることで、知らない言葉を別の未知語で置き換えるだけの説明から進めます。')),
    ('二つの公的資料にある名称と説明',p('姫街道と銅鐸の歴史民俗資料館の案内は、うげ・はぜかごなどの漁具と、囲目網漁の展示を説明します。浜松市史の該当節は、袋網・囲目網・刺網・ウナギ筒などの漁法を述べ、はえまわし網を刺網に対応させています。'+cite('oku_hamana_museum','資料館・民俗資料展示')+cite('hamamatsu_fishing_history','浜松市史四・浜名湖の漁法'))+table(['資料の名称','本文から確認できる説明','語の種類として読むもの'],[['うげ','魚を誘い入れる籠状の漁具','実物と捕獲の仕組み'],['はぜかご','籠に入ったハゼを捕る用具','対象魚を含む物の名'],['囲目網漁','魚を網で囲い込む漁の説明','漁法のまとまり'],['はえまわし網（刺網）','市史が併記する呼称','当該資料内での名称の対応']], '別資料の説明を保持して並べた比較')),
    ('名付けの観点を、対象・形・動きで整理する',p('はぜかごという名称は、対象の魚と道具の上位語を組み合わせて読めます。一方、うげという語は文字の見た目から用途を推定しにくく、説明や実物との対応が重要です。透明に見える名前と、説明が必要な名前を区別しても、どちらが古いかはその印象だけでは決まりません。','囲目網漁のように行為を説明する語では、どんな魚を、どんな位置関係の網で捕るかが意味の一部になります。同じ魚を捕れるから同じ漁法、同じ網という漢字を含むから同じ道具とまとめず、仕組みの共通点と違いを表へ残します。','市史の異称の併記は、その箇所における対応を示す証拠です。現在の別の案内にある角立て網などへ、名称が似るという理由だけで広く対応を広げません。語の同定には資料の年代と具体的な構造を合わせる必要があります。')),
    ('博物館の説明と、現場の発話を区別する',p('展示解説は一般の来館者へ対象を伝える文章であり、漁業者の会話をそのまま記録したものではありません。読みやすく整えた呼称、専門的な分類、地元の通称がどこに現れるかを別々に見ます。片仮名や平仮名だけで方言らしさを判定しません。','また、歴史的な漁法の説明は現在の操業や遊漁の手引きではありません。このノートは文化と言葉の研究として読み、許可や漁期などの現在の条件を古い記述から案内しません。')),
    ('実物と名称を、一対一にしすぎない',p('調査表には、資料名、名称、形、素材、捕獲の仕組み、対象、年代、収蔵番号を置きます。一つの道具に複数の名がある場合と、同じ名で形の違う道具を呼ぶ場合を残せるようにすると、語と物の対応を検証できます。','学習では表を見て、語から分かる対象と、説明を読まなければ分からない仕組みを分けてみてください。地域の仕事の専門語を、珍しい呼び名のコレクションから、人と水辺の関係を読む知識へつなげられます。'))],
    ['oku_hamana_museum','hamamatsu_fishing_history'],'livelihood','同じ魚を捕る二つの漁具は、同じ意味の方言の別形？','対象魚が同じでも、道具の形や仕組み、操業のまとまりが違う場合があります。物・行為・対象を別々に比較します。')

    add('enshu-tatami-and-fibre-names','生業語彙・原料と製品','「遠州表・備後藺・琉球藺・イチビトカシ」は、何の名か',
    '奥浜名湖の資料館の説明から、産地を示す製品名、原料名、加工の道具名を区別する。',
    '土地の名を含む言葉でも、方言の分布を示すとは限りません。産地や製品の名、植物を指す名、材料を加工する道具の名を分けると、生業と言葉の結び付きが具体化します。',[
    ('同じ産業の語でも、指す段階が違う',p('畳表を作る仕事の説明には、育てる原料、加工する道具、できあがる製品、流通で用いる名が混在します。それらをすべて畳の別名として登録すると、仕事の仕組みが見えなくなります。語が指す対象を工程に沿って整理する必要があります。','土地の名を含む語も、一種類ではありません。その土地だけで使われる呼称、その土地で作られた製品の名称、別の土地の名をもつ原料の名称は、地名と言葉の関係が異なります。')),
    ('資料館案内に示された対象の違い',p('浜松市の資料館案内には、浜名湖周辺の藺草栽培と畳表生産、備後藺と琉球藺（七島藺）、七島藺分割機、イチビの皮を繊維にするイチビトカシ、遠州表の名称が説明されています。名称と用途の関係をこの資料の範囲で読みます。'+cite('oku_hamana_museum','資料館案内・藺草栽培と畳表の生産'))+table(['名称','資料から整理できる対象','混同しないこと'],[['備後藺・琉球藺（七島藺）','原料として説明される植物','畳表という製品名'],['七島藺分割機','原料を割くための道具','原料そのもの'],['イチビトカシ','イチビの皮を繊維にする道具','畳を織るすべての機械'],['遠州表','各地へ出荷された畳表の名','遠州だけで使う語という意味']], '原料・加工・製品の層を分けた編集表')),
    ('産地名を含むことと、地域語であること',p('遠州表という名は、地域と製品を結び付ける働きを持ちます。しかし、その商品が各地へ流通すれば、名も産地の外で使われることがあります。語が指す地域と、語を使う人の分布は異なる情報です。地域専門サイトではこの違いを示すと、産業史と方言研究を混ぜずに接続できます。','原料名についても、文字に含まれる地名からその一地点での栽培や伝来の経路を逆算しません。名称の歴史を調べるには、その名がいつどの資料に現れ、何の植物を指したかを別に確かめる必要があります。','イチビトカシのように加工を説明する道具名では、原料と機能との対応が重要です。語の中の要素がどこまで当事者に意味として意識されていたかという問題は、名称と用途が分かったことだけでは解決しません。現在の編集者の分解と、当時の語の分析を区別します。')),
    ('伝来の物語と、語の初出を分ける',p('資料館の案内には、栽培の始まりや奨励に関する伝承も記されています。その伝承を語の成立年の証明として用いず、伝えられている内容と、同時代の文書で確かめられる内容を分けます。製品の歴史、原料の歴史、名称の歴史は一致するとは限りません。','さらに、過去に重要だった産業の説明を、現在の栽培面積や生産の継続の証拠としません。昔の道具の保存は、現場の仕事が今も同じ形で行われていることとは別の事実です。')),
    ('材料が物になるまでを、名称でたどる',p('学習では、植物・加工道具・織る機械・製品・流通名という札を並べ、資料の各語を対応させます。複数の札に関わる語は、一つへ無理に押し込めず、その関係を説明してみてください。仕事の語彙が工程や地域をまたぐ仕組みを理解できます。','研究の記録では、製品の名が書かれた荷札や目録と、原料や道具を説明する資料を別種として保存します。原形と出典の対応が残れば、将来別の地域の資料と比較するときにも、同じ対象を比べているかを検証できます。'))],
    ['oku_hamana_museum'],'livelihood','「遠州表」という名なら、遠州だけで通じる方言だと決まる？','産地や製品を示す名と、語を使う人の分布は別です。流通によって地域外でも用いられる可能性を含めて調べます。')

    add('sappa-and-boat-classification','生業語彙・船の分類','「さつぱ」と「シラス船」は、同じ尺度の船名か',
    '郡誌の小舟と市の漁業別分類を比べ、船体・用途・操業の単位を読み分ける。',
    '船を指す語は、船体の種類を表すものと、使う漁業を表すものが混在します。小舟という対応語と漁業別の区分を、同じ分類階層の別名として扱わないことが大切です。',[
    ('「どんな船か」には複数の答えがある',p('船を説明する際は、大きさ、形、動力、材料、運ぶ物、行う漁業など、異なる観点で分類できます。一つの船が複数の分類に属することもあります。船の名を集めるときに、その分類の軸を付けなければ、似た語や違う語の比較が曖昧になります。','方言の見出しと産業案内の見出しを並べる際も、それぞれの資料の目的を確認します。語義の対応を残す資料と、仕事別に船を紹介する資料は、同じ問いへ答えるために作られたものではありません。')),
    ('小舟の記録と、漁業別の船の案内',gunshi('さつぱ')+p('郡誌の福島村のさつぱには小舟という対応があります。浜松市の「漁業別・船の種類」は採貝・海苔・シラス・大船・カキ養殖・たきや漁という見出しで船を説明しています。後者の分類には、漁業の対象や用途が多く含まれます。'+cite('gunshi','磐田郡誌・1246頁')+cite('hamamatsu_fishing_boats','浜松市・漁業別、船の種類'))+table(['比較の軸','例として読む表記','確認する資料'],[['大きさや一般的な種類','小舟に対応するさつぱ','郡誌の意味欄'],['用途・対象','シラス船・採貝の船','市の漁業別解説'],['動力と時代','動力船・無動力船','当該年代の市史・写真']], '分類の尺度を分けた表')),
    ('同じ船が、仕事の切替で別の説明を持ちうる',p('用途から付く名は、船体の型式と一対一に対応するとは限りません。船を何に使うかが変われば、話題の中で選ぶ説明も変わる可能性があります。語を船体の恒久的な固有名のように登録する前に、実際の指示対象を確かめます。','市史の昭和29年の説明には、小型の無動力船が複数の湖面漁業に使われたことが述べられています。これは年代を限った歴史記述として、用途の分類が船体を完全には分割しないことを考える手がかりです。現在の全船の運用を示すものではありません。'+cite('hamamatsu_fishing_history','浜松市史四・昭和29年の船の記述'),'郡誌の小舟という短い対応だけでは、さつぱの形・寸法・材料や、浜名湖のどの船型と一致するかまでは分かりません。両資料を並べる意義は、同じ物を比べるために必要な情報を明らかにする点にあります。')),
    ('写真が似ていても、名称の同定は別の作業',p('似た形の舟の画像を添えれば理解しやすく見えますが、当該語との対応を裏付けていなければ、その語の実物写真として示してはいけません。撮影地・時期・船の用途・名称を述べた資料をそろえ、参考画像とは分けて扱います。','また、船の区分には現在の制度や操業上の条件に関わるものもあります。このノートは語の分類を考える教材であり、過去の案内にある隻数や許可条件を現在の利用案内として転記しません。')),
    ('名・物・用途を三つの欄にする',p('調べる際は、聞いた名称、実物の識別情報、使用した仕事を分けます。船の所有者や操業者が同じかどうかも、名称の意味と別の情報です。名が同じでも対象物が違う場合、同じ船に複数名が使われる場合を記録できる表が必要です。','学習では「小さい」「シラスを捕る」「動力がない」という三枚が同時に一つの船へ付けられることを考えてみてください。言葉の違いをそのまま物の違いの数へ変換しない、語彙研究の基礎を具体的に学べます。'))],
    ['gunshi','hamamatsu_fishing_boats','hamamatsu_fishing_history'],'livelihood','シラス船・小舟・無動力船は、必ず別々の三隻を指す？','用途、大きさ、動力という異なる軸なので、一つの船に重なる場合があります。実物との対応を調べて判断します。')
    add('fish-names-growth-and-products','生業語彙・魚介の分類','シンコ・コハダ・コノシロ――魚の名は、種類だけを分けるか',
    '成長段階、魚の種類、加工品という違いから、浜名湖の取引の言葉を読む。',
    '魚介の名前は生物の種類と一対一ではありません。同じ魚の成長段階を分ける名、対象を広くまとめる名、加工品の名を区別すると、地域の食と仕事の分類を説明できます。',[
    ('生物の種類と、仕事で区別する単位',p('魚の呼び名を集める際、生物学上の種名だけを正解の欄にすると、成長や大きさによる区別、加工や取引のための区別が見えなくなります。同じ生物でも仕事の中で違う名を使うことがあり、一つの名が複数の対象をまとめる場合もあるからです。','地域の名前が共通語と違うかを調べる前に、何を区切るための語かを確かめます。大きさ、用途、加工の状態という分類軸が分かれば、漁獲から市場や食卓へ移る中で名前の選び方が変わる仕組みを考えられます。')),
    ('取材記事と市の解説にある具体例',p('県の浜名湖の取材記事は、コノシロが成長につれてシンコ・コハダ・コノシロと呼ばれることを紹介します。また市の船の解説は、海苔の原料を刈り取る仕事と、青海苔とクロノリを組み合わせた板海苔を説明しています。ここでは名称が指す段階の違いへ注目します。'+cite('market2024','静岡県2024・魚の説明')+cite('hamamatsu_fishing_boats','浜松市・海苔の船の節'))+table(['比較する名','区別の観点','同一視しないもの'],[['シンコ・コハダ・コノシロ','成長に伴う呼び分け','必ず三つの生物種という分類'],['魚の名と加工品の名','原料と製品の段階','原料の名だけで決まる商品の分類'],['浜名湖の混ぜのり','複数原料を組み合わせた製品','一つの植物・生物の種名']], '資料の例から、分類軸を取り出す表')),
    ('同じ対象が変わる場合と、対象が組み合わさる場合',p('成長段階の呼び分けでは、一個体が時間の経過とともに違う名前の範囲へ移りえます。加工品の命名では、複数の原料が混ざり、一つの製品として扱われることがあります。どちらも一名と一種の対応を崩しますが、変化の仕組みは異なります。','仕事の資料を記述するなら、採捕した状態、選別した状態、加工した状態を別にして、その時点での名称を残す方法が有効です。同じ魚の別名なのか、加工して別の対象として扱う名なのかを説明するためには、物の移動と工程を追う必要があります。','ただし、全国的にも使われるシンコやコハダを、浜名湖だけの方言として登録するのは適切ではありません。このノートの目的は、地域の仕事の中で使われる分類を見ることです。語の地域的な限定性とは別の軸として扱います。')),
    ('名前から大きさの境界を作らない',p('成長に応じるという説明があっても、何センチから名が変わるかという境界まで、この取材記事から一律に決めることはできません。地域・市場・時代や取引の条件をそろえた資料が必要です。別の産地の基準を浜名湖の実測として移しません。','同様に加工品の説明も、現在の全製品の配合や規格を示すとは限りません。言葉がどの段階の対象を指すかという分析と、具体的な商品の現行仕様は分けます。')),
    ('魚から商品への名前の移動を図にする',p('学習では、個体の成長を表す矢印と、原料が製品になる矢印を別々に描きます。そこへ資料の名称を置けば、名前が変わる理由を「地方で言い方が違う」だけにせず説明できます。分類軸そのものを学ぶ練習です。','今後の記録では、呼称の原形、対象の同定方法、大きさや状態、場所、年代、使用者の役割を添えます。写真があっても生物の同定が不確かならその留保を残し、名前の違いをすぐ別種の証拠にしないようにします。'))],
    ['market2024','hamamatsu_fishing_boats'],'livelihood','シンコ・コハダ・コノシロという三つの名なら、三種の魚を指す？','この資料では同じ魚の成長に応じた呼び分けです。生物の種類、成長段階、製品の区別を別々に考えます。')

    add('sericulture-house-memory','生業と家族の語り','長屋で蚕を飼った記憶を、誰の言葉として読むか',
    '岩田地区の養蚕の回想から、場所の名・家族関係・仕事の記憶が結び付く過程を読む。',
    '家の呼び名と仕事の関係は、建物の形だけでは分かりません。筆者が見た場所と、家族から聞いた過去の使い方を分けると、回想資料の証拠の位置を明確にできます。',[
    ('建物の名だけでは、営まれた仕事は決まらない',p('長屋という語を知っていても、その建物を住居として使ったのか、作業や保管に用いたのかは別に確かめる必要があります。一つの建物が時間を隔てて複数の用途を持つ場合、現在見える形と過去の仕事が直結するとは限りません。','民俗資料では、家族の語りによって建物の別の使い方が分かることがあります。ただし、そのときも自分が見たこと、他人から聞いたこと、後から推測したことを分けて読むことが重要です。')),
    ('岩田地区の家をめぐる回想',p('『いわた文化財だより』99号の飯田訓子「長屋のはなし」は、筆者が伯母から養蚕の話を聞いたこと、岩田地区で稲作と養蚕を組み合わせた暮らし、繭の市場、真綿の布団の回想を述べています。筆者の幼少時の実見と、伯母からの伝聞が含まれる文章です。'+cite('iwata_sericulture','いわた文化財だより99号・最終頁'))+table(['情報の層','コラムを読む際の区別','言葉の研究への接点'],[['場所の記憶','筆者が住んだ長屋','同じ建物の用途の変化'],['仕事の記憶','伯母から聞いた養蚕','語と作業・生活史の対応'],['製品の記憶','繭から真綿や布団へのつながり','原料・加工品・暮らしの対象']], '実見と伝聞を分けた読解表')),
    ('親族関係が、記憶の伝わる経路になる',p('この文章では、伯母と筆者という親族関係が、過去の仕事を知る経路になっています。親族呼称は単語の意味だけでなく、誰が誰から何を聞けたかという記憶の伝達の構造に関わります。家の歴史を語る人の位置を示す語として読めるのです。','ただし、伯母が語った内容がそのまま録音されているとは限りません。印刷されたコラムには、筆者が回想を聞き、文章として構成した段階があります。ここに書かれた共通語の説明を、伯母の遠州弁の逐語的な発話として引用しないようにします。','繭・真綿・布団は同じ物の別名ではなく、仕事と暮らしをまたぐ別の段階の対象です。原料がどのように使われ、誰がどの仕事を担ったかという関係を残すと、物の名称から家族の生活史へ進むことができます。')),
    ('刊行年を、回想された仕事の年へ置き換えない',p('この号が刊行された年と、筆者の幼少期、伯母が幼かった時期は一致しません。資料の年代を整理するときは、記録の時点、語られた対象の時点、現在の参照時点を別にします。2013年の出版物だから、2013年に同じ養蚕が行われていたという読み方はできません。','また、一家族の回想は地域の全世帯を均一に調べた統計ではありません。地域の様子を述べた部分を手がかりとしつつ、世帯ごとの仕事の組合せや季節の違いは別の資料で確かめます。')),
    ('家族の語りを、検証できる形で残す',p('生活史の記録には、語った人と聞いた人の匿名ID、対象となる時期、場所の公開範囲、実見か伝聞か、関連する物や写真の出所を添えます。親族の記憶をそのまま事実の一覧へ変えるのでなく、記憶が伝わった経路も資料として保存する方法です。','学習では、同じ文章の中から「見た場所」「聞いた仕事」「そこから考えたこと」を色分けしてみてください。人の呼び方、生業、家の空間という別のテーマが、一つの回想の中でどう接続されているかが分かります。'))],
    ['iwata_sericulture'],'livelihood','2013年の回想コラムにある仕事は、すべて2013年の現状？','刊行時点と回想対象の時点は別です。筆者の実見、家族からの伝聞、編集された文章を区別して読みます。')

    add('tea-process-and-skill-language','生業語彙・工程と技能','「合葉・合組・こくり」は、すべて「お茶を混ぜる」ことか',
    '茶の加工段階と春野・森の手揉製茶の工程名を比べ、専門語が区切る仕事を読む。',
    '同じ原料を扱う仕事でも、対象の段階と手の動きが違えば用語の体系が変わります。原料を混ぜる語と、茶葉を仕上げる工程名を、対象と順序から読み分けます。',[
    ('仕事の言葉は、動きだけでも材料だけでも決まらない',p('お茶という同じ大きな対象を扱っていても、摘んだ葉、一次加工した茶、仕上げた製品では状態が異なります。さらに、手で行う工程と機械を含む生産・流通の分類は、同じ単位で区切られるとは限りません。資料が何のために工程を分けたかを確かめます。','専門語を日常の動詞一つへ訳すと、動作の大まかなイメージは伝わりますが、どの状態のものをどの順序で扱うかが失われます。この区別こそ、技術を伝える言葉の重要な情報です。')),
    ('二種類の公的な工程資料',p('農研機構公開の2005年の研究集報では、生葉の混合を合葉、仕上げ段階の荒茶の混合を合組として区別しています。浜松市の2008年の文化財情報は、春野・森に関わる手揉製茶について、下揉み・中上げ・仕上揉み・乾燥と、その下位の工程名を示しています。'+cite('tea2005','野菜茶業研究集報2・節5')+cite('handtea2008','浜松市文化財情報1・手揉製茶'))+table(['語','資料での位置','対象・働き'],[['合葉','製茶前の段階','生葉の混合'],['合組','仕上げの段階','荒茶の混合'],['中上げ','手揉製茶の工程区分','資料では焙炉の清掃を伴う'],['こくり','仕上揉みの下位工程名','当該の技法の工程名として採録']], '生産・流通の分類と手揉の工程区分を比較')),
    ('同じ「混ぜる」でも、対象の段階が違う',p('合葉と合組の違いを説明するには、何を混ぜるかという目的語と、その作業が工程のどこにあるかを合わせる必要があります。混ぜるという動作だけの類似では、用語の対立が消えます。専門語が対象の状態を分類している例として読めます。','手揉製茶のこくりについては、現代語の音の印象や別分野の同形語から、動作の細部を決めません。公開資料が示す工程上の位置は確認できますが、身体の動き、力の配分、茶葉の状態を再現するには実演や技術の記録が必要です。','地域に伝わる技法の名称と、その工程語が地域だけに分布するかという問いも別です。春野・森の解説に現れる語を遠州の技術語として紹介しつつ、全国的な分布を調べた方言地図としては扱いません。')),
    ('流派と年代を残す',p('市の2008年の記事は倉開流の技法と伝承を述べています。その記述を現在の保持者数、活動日程、生産・販売状況へ更新したものとはしません。手揉の工程と、別資料の生産・流通の分類を比較する際には、技法・年代・説明の目的を付けます。','語形をそろえるために漢字を補う場合も、原資料の表記を残します。原注にない読みや語源を付けず、確かめた工程名と編集部の説明を分けることが再検証の条件になります。')),
    ('工程図に、対象の変化を書き入れる',p('学習では、生葉から荒茶、仕上げた茶へ進む線と、手揉の工程の線を別に作り、混ぜる対象や工程名を配置します。二つの図を無理に一対一へ対応させず、どの区分で資料の目的が違うかを考えてみてください。','研究記録には語の原形、工程上の位置、加工対象、技法、記録年、実演か文書かを残します。職業の言葉を覚えるとは、一般語への訳だけでなく、その言葉が仕事をどう区切るかを理解することでもあります。'))],
    ['tea2005','handtea2008'],'livelihood','合葉と合組は、どちらも混ぜるので常に交換できる？','この資料では混ぜる対象と工程が違います。動作の大まかな共通点に加え、生葉か荒茶かという区別を保持します。')

    add('parent-child-metaphor-in-taro','生業語彙・親族語の比喩','「親芋・子芋・孫芋」は、人の親族関係と何が共通するか',
    '磐田の海老芋を題材に、植物の増え方を親族語で説明する仕組みと、その限界を考える。',
    '親族語は人の関係だけでなく、物のつながりや段階を整理する比喩にも使われます。親芋・子芋・孫芋は、形の大小だけでなく、どこから生じるかという関係を読む具体例です。',[
    ('「親」の字がある対象は、皆人の親族か',p('仕事の言葉には、日常の人間関係の語を別の対象へ使うものがあります。その場合、元の語が持つ性質がすべて移るわけではありません。親・子・孫という関係語が植物を説明するとき、どの関係を取り出しているかを見ます。','磐田の海老芋は、地域の生業と親族語の比喩を同じ対象で考えられる例です。ここでは遠州独自の親族呼称として追加するのでなく、地域の仕事で使われる説明語の仕組みとして扱います。')),
    ('大学の解説と市の作業紹介を並べる',p('静岡県立大学の里芋の解説は、親芋を中心に子芋ができ、さらに孫芋が生じる関係を説明しています。広報いわたの海老芋特集には、芽かき・葉かき・土寄せなどの作業名が現れます。対象の関係と、そこへ加える作業を別々に読みます。'+cite('taro2023','県立大学2023・里芋')+cite('ebiimo2020','広報いわた2020年11月号'))+table(['言葉','説明の中心','混同しないもの'],[['親芋・子芋・孫芋','どの部分から生じるかという関係','大きさだけの順位'],['芽かき・葉かき','取り除く対象と作業','どちらも同じ対象という解釈'],['土寄せ','土を動かす作業と対象の関係','名称だけで分かる完全な手順']], '植物の関係と作業の対象を分ける')),
    ('関係を示す比喩は、単純な大きさの比喩ではない',p('親・子・孫という並びは、人の世代の関係を利用して植物のつながりを説明します。名前に親があるから常に最大、子があるから常に小さいという尺度に置き換えると、関係の情報が失われます。大学の海老芋の説明でも、出荷の対象と大きさは親子の名だけから決まりません。','この比喩では、どこから生じるかという連鎖が分かりやすくなります。一方、人の婚姻、社会的な親子関係、家の継承などの性質まで植物へ移るわけではありません。比喩が写す部分と写さない部分を示すと、親族語の意味を人以外へ広げる仕組みを説明できます。','作業名には目的語の違いもあります。芽かきと葉かきを、単に何かを取る同義語として覚えるのでなく、対象を語の中に組み込んだ動作名として読むと、農作業の知識と言葉の構造がつながります。')),
    ('名前を知ることと、技能を身に付けること',p('土寄せという語の意味を説明できても、土を寄せる量・位置・時機を実行できるとは限りません。市の特集は技術の承継や手作業の難しさを述べており、技能の一部が短い名称だけでは伝わり切らないことを考える手がかりです。','このノートは栽培マニュアルではありません。名称の語義と、個別の圃場条件に応じる技術を分け、細かな施肥量や作業時期の指導へ広げません。また、産地の仕事で使う語と、その地域だけに固有な方言の形は別に分類します。')),
    ('人の関係図と植物の関係図を比べる',p('学習では、人の親子孫の図と、資料の親芋子芋孫芋の図を並べ、共通して表す関係と異なる性質を列挙してみます。意味の広がりを説明するとき、同じ単語を使うことが対象の完全な一致を意味しないことが分かります。','記録する際は、呼称を使った人の役割、作業対象、植物のどの部分か、説明の場面を残します。家庭で食材として語るときと、畑で作業を教えるときでは、同じ語でも必要な知識の範囲が変わる可能性があります。'))],
    ['taro2023','ebiimo2020'],'livelihood','親芋という名なら、必ず子芋より大きいと分かる？','親子孫という名は関係の連鎖を示します。大きさ・出荷対象・食べる部分は別の条件で確かめます。')

    add('yotabi-work-time','生業語彙・仕事の時間','「ようたび」を夜なべと訳すと、どこまで仕事が分かるか',
    '夜を表す仕事の名と、作業内容・担い手・生業の組合せを分けて読む。',
    '仕事の語は、何をするかだけでなく、いつするかという観点でも成り立ちます。夜業という対応が分かっても、その作業、担い手、賃金の有無まで一度に決まるわけではありません。',[
    ('仕事の分類に、時間という軸がある',p('生業の名前を農業・漁業・織物という産業別に並べると、一日の中の作業の組合せが落ちます。昼と夜、農繁期と農閑期、家の作業と外の仕事という時間の分け方も、仕事の語彙を読む重要な視点です。','一つの仕事の名に見える語でも、内容ではなく行う時間を取り出していることがあります。何をするかという分類と、いつするかという分類を別にすれば、同じ語の下に異なる作業が入りうることを説明できます。')),
    ('郡誌の一行にある夜業の対応',gunshi('ようたび')+p('袋井町のようたびは夜なべに対応し、原注には夜業とあります。この一行には、具体的な製品、作業者、勤務時間の長さは示されていません。意味の核として確認できる時間の情報と、記録されていない作業の条件を分けます。'+cite('gunshi','磐田郡誌・1253頁'))+table(['問い','この記録からの位置付け'],[['いつの仕事か','夜なべ・夜業という対応がある'],['何を作ったか','具体的な品目はこの行では不明'],['誰が担ったか','性別・年齢・家族関係はこの行では不明'],['どう評価されたか','負担や報酬の情報は別の資料を要する']], '一語の意味と仕事の実態の区別')),
    ('産業別の箱を横断する言葉',p('時間を基準にする語は、特定の産業だけに閉じない可能性があります。ただし、夜業という上位の説明があることから、実際にどんな複数の仕事へ使ったかまで想像で増やすことはできません。作業の記録に語が現れたときに、その対象との対応を積み重ねます。','日記や家計の帳面に作業が書かれていれば、時刻、季節、作った物、手伝った人を対応させられます。単語の記録と生活の記録を同じ日時や人物へ結び付けられれば、何を夜の仕事としてまとめたのかをより具体的に検討できます。','この方法は、家の仕事を単純な副業と決めないことにもつながります。産業別の公的分類と、当人が一日の仕事を区切る語は同じとは限らず、記録の作り方によって見える作業が変わるからです。')),
    ('担い手の属性を、イメージで補わない',p('夜なべという訳から、特定の性別や年齢の人が裁縫をしていたという場面を自動的に作ることはできません。古い資料を教材にする際、分かりやすい挿話が実際の証拠と入れ替わらないように注意します。','また、原資料の夜業を、現代の雇用制度における勤務区分へそのまま換算しません。語義の説明、生活時間の記述、制度上の分類は異なる資料と条件を必要とします。')),
    ('一日の時間表へ、確かめた作業だけを置く',p('学習では、産業名と時間帯を縦横にした空の表へ、出典で確認した情報だけを置きます。ようたびは夜の欄へ置けますが、具体的な製品の欄は空欄のまま残せます。空欄を埋めないことも、資料に忠実な読解です。','調査では、語を聞いた場面、作業の対象、対象となる年代、記録した日を分けます。仕事の語彙を生業の一覧から生活時間の分析へ広げるには、この対応が役立ちます。'))],
    ['gunshi'],'livelihood','ようたびという語があるので、誰が何を作ったかも確定できる？','この記録は夜なべ・夜業という対応を示します。作業内容や担い手は、日記などの別の記録との照合が必要です。')

    add('noriko-and-seasonal-work','生業語彙・担い手と季節','「乗り子」は漁師の別名か――仕事の役割と兼業を読む',
    '浜松市の産業解説から、職業名・乗組員の役割・季節ごとの仕事を区別する。',
    '一人が複数の漁業へ関わる場合、職業を一つの魚や漁法の名で固定できません。乗り子という役割の名と、生業を組み合わせる営みを分けて読む必要があります。',[
    ('人の仕事を、一つの名へ閉じ込めない',p('人の呼び方を職業と結び付けるとき、ある人が一年を通じて同じ対象だけを扱うと想定すると、季節による作業の移動や複数の仕事への関与が落ちます。職業名は人の生涯を一語で表す札ではなく、特定の場面での役割を示すこともあります。','乗り子という語を読むときには、漁業に関わる人という大きな分類と、船に乗り組む人という役割を分けます。誰を何の仕事との関係で呼んだかを明示すると、人の呼称と生業の構造を接続できます。')),
    ('市の説明にある役割と組合せ',p('浜松市の水産業の概要は、複数の漁業を組み合わせる例としてシラス漁とノリ養殖などを挙げ、シラス漁の乗り子に乗組員という説明を添えています。この資料の説明を、語と役割の対応を読む出発点にします。'+cite('hamamatsu_fishing_work','浜松市・沿岸漁業、湖面漁業の節'))+table(['分類の軸','確かめる内容','別にするもの'],[['産業・漁業','シラス漁・ノリ養殖など','個々の人の固定した肩書'],['作業上の役割','乗り子＝乗組員という説明','船の所有や経営の条件'],['時間の組合せ','季節や時期による仕事の組合せ','一種類だけを続けるという想定']], '職業・役割・時間を分ける編集表')),
    ('役割の語は、相手との関係を含みうる',p('乗組員という役割は、船やその操業との関係で理解されます。一方で漁業者という大きな分類には、経営、養殖、採貝など異なる仕事が含まれます。二つの語が同じ人を指す場面があっても、意味の範囲が完全に同じとは限りません。','複合する生業を調べる際には、どの時期に何の仕事へ参加し、どの相手と働くかを対応させます。交流する人が仕事ごとに変わるなら、覚える道具の名や共有する略称も変わる可能性があります。これは検証すべき仮説で、今回の産業案内から実際の語彙の差が測定されたわけではありません。','地理的には同じ場所に住み続けても、仕事を通じて接する人の範囲は変わりえます。地域方言の研究へ職業の条件を加える意義は、地図の境界だけでは見えない人のつながりを調べられる点にあります。')),
    ('役割名から、雇用条件を推定しない',p('乗り子という説明から、船の所有関係、報酬の分け方、雇用契約の条件まで決めることはできません。これらは個々の時代と事業の資料に基づいて確認する別の問いです。語の意味だけを現代の制度上の区分へ移しません。','市のページには年次の異なる統計も含まれます。このノートでは役割語と仕事の組合せの説明を参照し、古い人数や水揚げの値を現在の産業の規模として再掲しません。')),
    ('人・役割・時期を対応させる',p('匿名の記録表に、一人の人、関わった仕事、作業上の役割、時期、働く相手の集団を置けば、一語では表せない仕事の組合せを検討できます。名の違いを人数の違いと決めつけず、一人に複数の記述が重なることを残します。','学習では「この人は何の仕事をする人か」と「この場面で何の役割を担うか」を別々に答えてみてください。人の呼称から、地域の生業を固定した職業一覧としてではなく、時間と関係の組合せとして読めます。'))],
    ['hamamatsu_fishing_work'],'livelihood','乗り子と呼ばれる人の船の所有や報酬まで、この語だけで分かる？','資料で確認できるのは乗組員という対応です。所有・経営・報酬の条件は別の証拠で確かめます。')
    add('atago-paper-craft-explanation','生業と言語・技能の説明','「漉かにゃあ、ならんでのう」を、職人の説明の中で読む',
    '阿多古和紙の取材記事を、語尾だけでなく、条件と作業の基準を伝える発話として精読する。',
    '仕事の中の遠州の言葉は、方言らしい語尾を取り出すだけでは説明し切れません。紙の厚さという基準と、原料の状態へ応じる技能を伝える発話として、前後の説明と一緒に読む必要があります。',[
    ('語尾だけを抜き出すと、何が失われるか',p('仕事の取材に方言の表記があると、末尾の形だけを珍しい表現として拾いがちです。しかし、何について判断を求め、どの条件に応じる必要を伝えているかを見なければ、その発話が果たす役割は分かりません。語彙や文法を、生業の中の行為へ戻して読むことが大切です。','阿多古和紙の取材記事は、紙を作る人の説明を印刷された言葉として示しています。音声そのものではありませんが、何を説明する場面でどの形が用いられたと編集されているかを、本文で確かめられます。')),
    ('同じ厚さにすることを説明する箇所',p('市の記事には、原料の濃さが違っても製品の厚さをそろえることを述べる中に、職人の言葉として「漉かにゃあ、ならんでのう」という表記が現れます。原料の状態に応じて漉き方を調節する説明と合わせて読む箇所です。'+cite('atago_paper_voice','浜松市・阿多古和紙を漉く人'))+table(['発話の中で見る層','この箇所を読む問い'],[['対象','何を漉くのか、どの状態の原料か'],['基準','何を同じにする必要があるか'],['必要性の表現','しなければならないという関係をどう示すか'],['説明の場','誰が、何を知らない相手へ説明しているか']], '引用箇所の機能を読む編集部の分析表')),
    ('必要性の表現は、条件と結果をつなぐ',p('この発話を読む際、単純な禁止や相手への叱責として分類するより、製品として求める結果と、その結果を実現する行為の必要性を結び付ける表現として考えられます。会話の行為は、表現の形だけでなく、説明する対象と前後関係から判定します。','原料の状態が変わっても結果をそろえるという点には、同じ動きをいつも繰り返すだけでは足りない技能の特徴が現れています。語として説明される基準と、動作で調節する部分を分けると、言語だけで伝わる知識と実演を要する知識の接点が見えます。','本文にはコウゾの原料の説明もありますが、郡誌の熊村のかずという植物名と、その職人が実際に使った語形を同じと決めることはできません。地域・時代・記録形式を残し、原料の同定と方言形の対応を別に検討します。')),
    ('印刷された発話の表記が示さないもの',p('記事にある仮名から、正確な発音、イントネーション、間、聞き手のうなずきまでは復元できません。でのうという末尾を、この一人の全場面や天竜全域で同じ意味に使う語尾として一般化しないことも必要です。','ページの更新日は取材の実施日と同じとは限りません。取材記事の公開情報、発話の対象となる作業、編集部が参照した日を別に残し、新たに現地で聞いた発話として表示しません。')),
    ('文法と技能を、一つの資料の中で読む',p('学習では、引用の形を現代の一般的な言い方に置き換えた後、何の必要性を説明しているかを一文で書きます。それから、原料の濃さと製品の厚さの関係を図にします。方言の形を覚えることと、発話の意味を状況から理解することを接続できます。','今後の調査なら、実演と発話を同じ時刻で対応させ、指示の対象や道具の位置を残す方法が有効です。録音や実演の新規資料が得られるまでは、確認できた印刷本文の範囲で分析を示します。'))],
    ['atago_paper_voice','gunshi'],'livelihood','この発話の語尾が分かれば、紙漉きの技能も説明し終えた？','語尾の分析に加え、原料の条件、製品の基準、実際の調節を区別します。印刷本文は動作と音声の全記録ではありません。')

    add('craft-names-and-jisshoku','職業呼称・歴史的な分類','「十職」は、いつでも十種類だったのか',
    '浜松の職名の一覧から、数字を含む総称と、文書ごとの分類の違いを読む。',
    '数字を含む呼称は、実際の一覧の件数と常に一致するとは限りません。十職という総称の下で職種の含め方が文書により異なることは、名前と社会的な分類の関係を考える事例です。',[
    ('総称の数字を、先に答えにしない',p('ある集団の名前に数字が付くと、その数だけの成員が固定されていたと考えやすくなります。しかし、総称が続く一方で、対象の範囲や役目が文書ごとに異なる場合があります。名前と、その時点の分類表を照合する必要があります。','職人を表す言葉には、作る物、行う作業、役割、店の名など、複数の命名の観点が混在します。現代の職業分類の表へそのまま置き換える前に、史料中で何をまとめた呼称かを確かめます。')),
    ('市史が指摘する十職の揺れ',p('浜松市史の「十職の職種」は、大工・木挽・畳師・瓦師・檜物師・鍛冶屋・塗師・桶師・仕立師・紺屋・屋根屋を挙げます。十職から仕立師を除くという説明がある一方、実際の文書では除かれる職が一定しないことを述べています。'+cite('craft_history','浜松市史二・十職の職種'))+table(['資料を読む単位','確認すること'],[['総称','十職というまとまりの名'],['列挙された職名','その文書に何が含まれるか'],['行為と役目','願い出・作料など何の場面の一覧か'],['表記の末尾','師・職・屋等をどう用いているか']], '総称と個々の一覧を別に読む枠')),
    ('同じ一覧でも、作る物と働く人の捉え方が違う',p('畳師や桶師は製品と人の関係を、木挽は作業の観点を読み取りやすい形です。ただし、師・屋・職という文字だけから身分の上下を順位付けすることはできません。表記の形と、社会的な扱いを示す記録を区別します。','十職の範囲が揺れるという市史の記述は、昔の人が数を誤ったという説明ではありません。名前が制度上の総称として機能することと、特定の用件で名を連ねる職種の範囲が一致するとは限らない、という問題として考えられます。','現在の地名や屋号に職業に関する要素が見える場合も、同じ原理で形と来歴を分けます。職種の名が含まれること、そこでその職が営まれたこと、住民がその名で人を呼んだことは、別々の証拠を必要とします。')),
    ('地域の産業史の用語を、すべて方言にしない',p('この一覧は浜松の歴史的な仕事と制度の資料です。そこにある大工や鍛冶屋などの語が遠州だけに固有な形式だという意味ではありません。地域の専門サイトでは、地域の中で使われる制度語・職業語と、語形の地域差を持つ方言を別の軸として説明します。','市史が参照する個々の願書や作料の原本を今回直接検査したわけではありません。市史の分析として確認できたことと、原史料に戻って再検証する余地を明示します。')),
    ('名前・一覧・用途を三段で記録する',p('比較表には総称、個別の職名、一覧の年代、作成された用件、名を記した主体を残します。同じ総称の一覧を並べて、含まれるものと含まれないものを照合すれば、分類がどの条件で動くかを検討できます。','学習では、市史に列挙された職名を数えた後、その数字と十職という呼称が一致しない理由として、どの追加資料を読みたいか考えてみてください。語の意味を知ることから、社会的な分類が運用される仕組みの研究へ進めます。'))],
    ['craft_history'],'livelihood','十職という総称なら、どの史料の一覧も同じ十項目に直せばよい？','市史は文書による範囲の違いを指摘しています。数へ合わせて項目を削らず、原文の一覧と作成目的を保持します。')

    add('ferry-person-role-and-right','仕事の呼称・役割と権利','「居番・船頭・舟名敷」は、同じ種類の仕事名か',
    '船越村の渡船の記述から、指揮する役、働く人、勤務の割当と関わる持高を読み分ける。',
    '仕事に関わる名でも、人の役割を指すものと、権利や割当を示すものは違います。渡船の組織を語だけの職業一覧へ変換せず、人・役・持高という関係として読む必要があります。',[
    ('仕事の資料に現れた名は、皆職業名か',p('地域の仕事を説明する文章には、働く人の呼称のほか、役職、勤務の単位、権利や負担の名が現れます。それらをすべて職業名として索引に入れると、人ではない対象を人の肩書へ変えてしまいます。まず何を指す語なのかを分けます。','渡船のような共同の仕組みを持つ仕事では、一人がどの役を担うかと、どの持高に応じて働くかが重なることがあります。語の意味を制度の関係へ置いて読む必要がある場面です。')),
    ('市史の船越村の記述',p('浜松市史は、当番の日に居番と呼ばれた渡船役人が船頭を指揮したこと、出勤日数の割当が舟名敷の持高に応じて行われたことを説明しています。舟名敷は移動しうる持高として述べられ、単に船で働く人の別名ではありません。'+cite('ferry_history','浜松市史二・船越村の渡船労務組織'))+table(['語','市史が示す対象','分析上の区別'],[['居番','当番の日の渡船役人','指揮・管理に関わる役'],['船頭','指揮を受けて渡船に勤務する人','作業の担い手'],['舟名敷','割当に関わる持高','人そのものではなく権利・割当の関係']], '人を指す語と制度上の対象を分ける')),
    ('役割を指す名と、同じ人を指す名',p('一人の人が船頭として働き、別の文書では持高を持つ主体として現れる場合でも、二つの記述の意味は同じではありません。人が重なることから語の同義性を判断せず、どの関係を取り上げているかを述べます。','居番と船頭の違いを読むときも、日常会話で互いをどう呼んだかという問いとは分けます。市史が組織の説明に用いる役名が確認できても、作業中の呼びかけや名前の省略の仕方が分かったわけではありません。','仕事の記述には、個人、家、役割、権利の持分という異なる単位が混在しやすくなります。これらを別欄にすれば、人の呼び方と家の経済を結び付けつつ、同じものとして扱う誤りを防げます。')),
    ('歴史的な持高を、現代の制度へ直結しない',p('市史の表現にある株式化という説明は、歴史的な権利の持分を理解するための記述です。現代の会社の株式や勤務契約と同一の制度だと説明しません。言葉の似方と制度の同一性は別に検証する必要があります。','また、特定の年の持高の表を、すべての年代の村の組織と見なさないようにします。語が続いても、持高の分布、担い手、役割の運用が変わる可能性を残します。個人別の表を転載することなく、分析に必要な関係を整理できます。')),
    ('一人・一役・一持分を別々の札にする',p('学習では、人の札、役の札、持高の札を作り、どの関係で結ぶかを考えます。一人の札に二つの役が重なる可能性も、同じ役を時期で交替する可能性も表せます。名称の数をそのまま人数へ置き換えない練習です。','今後の研究では、役名の原表記、資料の年代、出勤の記録、持高の記録、呼びかけの発話を別資料として対応させます。地域の仕事と言葉を深く読むには、語の意味の区別と、社会関係の単位の区別が両方必要です。'))],
    ['ferry_history'],'livelihood','舟名敷を持つ人と船頭が同じ場合、舟名敷も船頭の別名？','同じ人に関係していても、一方は持高、他方は働く人の役割です。対象の種類と関係を分けて読みます。')

    add('kawadome-kawaake-and-signs','生業と文書・状態の名','「川留・川明」は、川そのものの変化をいうのか',
    '天竜川の渡船と川会所・立札の記述から、自然の状態と運用上の判断を区別する。',
    '川の名を含む表現でも、自然現象だけを指すとは限りません。渡船を止め、再開を知らせ、旅人や荷物を動かす仕組みの中で、状態を表す語が機能します。',[
    ('水の変化と、人の移動の条件',p('川が増水することと、渡船を止めることは関係しますが、同じ出来事を別の言い方で呼ぶだけとは限りません。自然の状態、運用の判断、旅人へ伝える情報という層を分けると、仕事の言葉が何を区切るかを説明できます。','川留・川明という対を読むときも、文字の留める・明けるだけから川の見た目を想像するのでなく、資料が述べる渡船や輸送の場面へ置きます。')),
    ('市史にある渡船と知らせの仕組み',p('浜松市史の該当節は、大雨による増水で船渡しが中止され、旅人が川明を待つことを説明します。川会所、川立札、荷物や御用物の継送に関する記述もあり、語が交通の運用と結び付いていることを確認できます。'+cite('river_status_history','浜松市史二・川留と川明'))+table(['資料を読む層','具体的な対象','言葉の働き'],[['自然の条件','増水・流れ','判断の背景となる状態'],['運用','渡船の中止・再開','人や荷物を動かせる条件'],['伝達','川会所・立札等','状態や取扱いを関係者へ知らせる']], '川の状態と交通の状態を分ける')),
    ('状態の名が、次の行動を可能にする',p('川明を待つという表現では、単に川を眺めて変化を待つだけでなく、移動を再開できる状態との関係が示されます。名前は自然の描写と人の行為をつなぎます。このような語は、対象物の名だけではない生活語彙の重要な部分です。','状態を知らせる札や役所への連絡があるなら、誰が知り、誰へ伝え、どの段階で人や荷物が動くかという情報の経路を調べられます。書かれた名称と、口頭での知らせが同じ形であったかは別の問いとして残します。','語の対を考える際も、留と明を完全に対称な二つの行為と決めず、個々の記録で何を表すかを読みます。止める判断と再開の判断で必要な手続きが同じかどうかは、別途資料を照合する対象です。')),
    ('当時の引用と、現代の説明を区別する',p('市史には宿大概帳などからの引用が含まれます。今回確認したのは市史の公開本文であり、引用元の原本を独立に調べた翻刻ではありません。市史の説明、引用文、編集部の分析を分けて表示します。','この語を地域の歴史の教材として読むことと、現在の川の安全や交通の可否を判断することは別です。過去の状態名を現行の運航・防災情報として案内しません。')),
    ('一つの出来事を、状態・判断・伝達へ分ける',p('学習では、増水、渡船を止める判断、旅人への知らせ、待機、再開という出来事を順序に置いてみます。資料にない手続きを補わず、どの段階が本文で確かめられるかを示してください。語の意味を、時間の流れの中で理解できます。','研究記録には名称、対象となる状態、判断する主体、知らせる媒体、行動の変化、年代を残します。生業の言葉を、物の名から制度とコミュニケーションの働きへ広げる方法です。'))],
    ['river_status_history'],'livelihood','川明と書かれていれば、天候や流れだけを説明した文だと分かる？','この市史では渡船や輸送の再開の条件と関わります。自然の状態、運用の判断、知らせる行為を分けて読みます。')
    add('kureki-transport-and-counting','生業語彙・材木と数量','「榑木・管流し・筏送り」は、同じ材をどう捉えるか',
    '掛塚湊の市史記述から、年貢材・運ぶ工程・数える単位を別々に読む。',
    '同じ木材でも、納める対象、運送の仕方、まとまりの数え方によって言葉が変わります。物の同一性だけでは、仕事の語の意味や数量の単位は決まりません。',[
    ('同じ物を、別の関係から名付ける',p('木材を運ぶ文章には、樹種、納める品目、運び方、束ねたまとまり、数量の単位が現れます。それらを木の別名として一つにまとめると、生業や制度の関係が失われます。何の観点でその対象を呼んだかを残します。','掛塚湊は、山から下ろした木材と海上の輸送がつながる場所として資料に現れます。同じ材を追うことで、山・川・湊という場所の違いに加え、仕事の段階による名前の使い分けを考えられます。')),
    ('市史が説明する榑木と運送の段階',p('「掛塚湊と榑木」の節は、榑木を米に代えて納める年貢材として説明し、天竜川を管流しで下った材を集め、筏に組んで掛塚へ送る流れを述べています。本文には挺と艘という数え方も現れます。'+cite('kureki_history','浜松市史二・掛塚湊と榑木'))+table(['言葉・単位','指す関係','分けて読む情報'],[['榑木','納める材としての位置付け','樹種の名前とは別'],['管流し','川を下す運送の工程','材をまとめる前の扱い'],['筏送り','材を筏にまとめて送る工程','まとまりとしての運送'],['挺・艘','材や筏を数える単位','個々の材と運送のまとまり']], '物・制度・工程・単位を分ける表')),
    ('数える対象が変わると、同じ数量では比べられない',p('材を一本ずつ数える場合と、筏のまとまりを数える場合は、数えている対象が違います。艘という語があるから、一定量の木材へいつでも換算できるとは限りません。市史も材の長さや太さ、時代でまとまりが異なることを述べています。','榑木という名についても、樹種と納める品目を分けます。同じ樹種の木がすべて同じ制度上の品目になるわけではなく、納め方や規格との関係を考える必要があります。物の自然的な分類と、取引・租税の分類を重ねて読むことができます。','運送の工程の名は、個々の道具だけでなく、何をどんなまとまりで動かすかを示します。キンマのような山の運搬具の解説と接続する際も、地域と時代の違う資料を一つの実録へ合成せず、それぞれの工程がどの資料で確認できるかを示します。')),
    ('昔の数を、固定した換算式へしない',p('市史に示された筏一艘の材数の例を、全時代の標準として採用すると、資料自身の留保を失います。数量を引用する際は、単位、対象物、規格、年代の四つを残す必要があります。','また、管流という文字の読みを現代の一般的な音読みで置き換えず、市史に付された読みを当該資料の情報として扱います。読み、技法、地域語としての分布はそれぞれ確認する対象です。')),
    ('物の経路へ、名前と単位を添える',p('学習では、山、集積する場所、筏、掛塚湊を結ぶ経路に、納める物の名、運ぶ行為、数える単位を書きます。同じ材の移動の中で、どこで数える対象が変わるかを考えると、仕事の語彙の構造が分かります。','研究記録には、名称の原形、物の状態、制度上の位置、工程、数量、単位、資料の年代を分けます。地域の生業を語から説明するとき、対象の同一性と分類の違いを両方残す方法です。'))],
    ['kureki_history','sakuma2012'],'livelihood','筏一艘という単位なら、時代を問わず材木の本数へ換算できる？','市史は材の寸法や時代による差を述べています。数えている対象と規格をそろえず、一定の換算式にはしません。')

    add('salt-bale-and-measure','生業と言語・数量表現','塩の「一俵」は、入れ物の数か、決まった量か',
    '浜松塩町の取引をめぐる記述から、単位の意味と、当事者間の基準の違いを考える。',
    '同じ一俵という語でも、容器としてのまとまりと中身の容量が一致するとは限りません。数量表現の理解には、数詞と単位だけでなく、当時の取引で何を基準にしたかという情報が必要です。',[
    ('数字が同じなら、同じ量か',p('昔の文書に一俵とあれば、現代の特定の重量へ直ちに置き換えたくなることがあります。しかし、何を包み、どの容量や規格を基準にしたかを確認しなければ、比較の条件はそろいません。数える容器と中身を分ける必要があります。','数量の語は取引を進めるための共有基準として働きますが、その基準が争点になる場合もあります。言葉の意味が常に完全に一致してから取引が行われるのではなく、実際の交渉で意味の範囲が問題になる場面を資料から読めます。')),
    ('1713年の塩俵の容量をめぐる説明',p('浜松市史は、塩問屋が一俵を四斗入とする基準を求めたのに対し、宇布見・山崎側との争いで三斗五升ほどの容量や相場の慣習が問題になったことを述べています。ここでは一つの俵の量が、当事者の要求と慣習の違いを含む争点として現れます。'+cite('salt_capacity_history','浜松市史二・製塩業者との紛争'))+table(['読む対象','分ける問い'],[['一俵という表現','何のまとまりを数えるか'],['容量の説明','どれだけ入るとするか'],['取引の基準','誰がどの慣習を採用するか'],['価格・値引きの主張','どの量を前提に比較するか']], '数・容量・基準・評価を分ける編集表')),
    ('単位の意味は、社会的な取り決めを含む',p('一俵を一つの容器として数えるだけなら、二つの俵は二俵です。しかし、二俵が同じ量を表すかを比較するなら、中身の規格を要します。数え方の一致と、計量の一致は別の条件です。','この違いは、語の多義性だけでなく、当事者がどの基準を使うかという社会的な問題でもあります。文書で一方が正量と主張したことを、その時代の全地域で実施された唯一の量と読み替えないようにします。争いの記録では、誰の主張かを明記することが意味の読解に必要です。','職業の専門語を理解するには、単位を覚えるだけでなく、その単位で何を比較し、どんな行為を要求したかを読むことが役立ちます。数量表現は、物の数と人々の取引の関係をつなぐ言葉でもあります。')),
    ('容量と重量を、資料なしに交換しない',p('斗や升による容量の説明を、塩の重量へ変換するには別の条件が要ります。このノートでは現代のキログラムに換算しません。塩の状態や詰め方などの情報がないまま一つの値へ変えると、原資料が示した争点を消してしまいます。','また、今回確認したのは市史の公開本文です。引用元の江間文書や関係資料の原本を独立に検査した成果ではなく、市史の説明を通じて数量の言葉の問題を考える教材です。')),
    ('史料の数量を、条件付きで記録する',p('記録表には、原表現、数詞、単位、対象物、容量や規格の説明、主張した人、年代を残します。相対する主張は別行にし、一つの正解の数へ整形しないことが重要です。','学習では、一俵という同じ語を使う二人の主張を比べ、どの部分は一致し、どの基準が争われているかを説明してみてください。地域の仕事の言葉を、単語と訳語の対応から、実際の交渉の意味へ広げて読めます。'))],
    ['salt_capacity_history'],'livelihood','史料に一俵とあれば、同じ重さのものが一つだと確定できる？','容器のまとまり、容量、重量、取引の規格は区別します。その史料で何を基準に一俵としたかを確認する必要があります。')

    add('salt-boundary-language','生業と言語・境界の解釈','「傍示」の内とは、どこまでか――塩の商圏をめぐる言葉',
    '県立図書館の史料解説から、場所を指す表現の曖昧さと、取引の範囲の関係を読む。',
    '地名や範囲を示す語があっても、境界が一つに確定するとは限りません。どこまでを含むかという表現の解釈は、地域の仕事や専売の利害と結び付くことがあります。',[
    ('地名の列挙は、精密な境界線と同じか',p('地域を示す文章に川、湊、山の名が並んでいても、現代の地図で一本の境界線を引けるとは限りません。場所の名のほかに、どこまでを含めるか、どの方向へ範囲を取るかという解釈が必要になるためです。','方言研究では語の地域分布を地図へ示しますが、生業の資料には、売買や通行などを許される範囲を言葉で表したものもあります。言語の分布域と取引の範囲は異なる地理情報として読む必要があります。')),
    ('塩の専売圏を説明する資料',p('県立中央図書館の「浜松塩町の専売圏をめぐる争論」は、史料で専売圏を傍示の内と表すことや、二俣から山地をどこまで含めるかという解釈の違いが争論に関わったことを解説しています。今回確認したのは、この公開された史料解説です。'+cite('salt_boundary_history','県立中央図書館・解説36、80–81頁'))+table(['区別する範囲','何を示すか','別にするもの'],[['地名が指す場所','二俣などの地点や地域','取引を認める範囲全体'],['制度上の範囲','塩の売買に関わる内外','住民の方言の分布'],['解釈された境界','誰がどこまで含めるか','現在の行政区域']], '同じ地理情報へ統合しないための表')),
    ('範囲の語は、行為の条件を定める',p('内と外の区別は、場所の位置を示すだけでなく、その場で何ができるかという行為の条件に関わります。同じ土地でも、魚の販売、塩の取引、別の産物の流通では範囲や条件が違う可能性があり、一つの商圏で地域社会をすべて説明しないことが大切です。','また、曖昧な表現は単に書き方が不正確だったという問題にとどまりません。複数の当事者が異なる範囲を主張する際、同じ地名や内外の表現を別の意味で使うことがあります。誰が、どんな目的で、その範囲を述べたかを記録すれば、言葉の解釈と社会的な利害の関係を検討できます。','これは語の指す対象が会話や文書の文脈に依存する例として読めます。語義の欄に傍示の共通語訳だけを置いても、どこに線を引くかという実際の争点は解消しません。文の中で何を含めたかを読む必要があります。')),
    ('原文の曖昧な箇所を、勝手に明確化しない',p('古い文字を読み取り、地図へ配置する場合、解説者が示した複数の解釈を保持します。今回、原文画像の細かな字を独自に翻刻し、唯一の境界を復元したという主張はしません。資料が述べる不確定性を残すことが、地理的な説明の精度につながります。','また、史料解説の古い行政区名を現行区名の証拠として使わず、歴史上の地域名と現在の制度を分けます。歴史の取引範囲を、現代の規制や権利の案内へ転用しません。')),
    ('地図に線を引く前に、主張を並べる',p('学習では、一つの白地図へ正解の線を引く前に、史料にある場所、範囲を述べた主体、含め方の違いを表にします。資料の言葉から直接分かるものと、解釈を加えて描くものが区別できます。','研究記録には原表現、資料の年代、発言・作成の主体、対象となる取引、地理の解釈、未確定部分を残します。人々が地域を言葉で区切る仕組みは、仕事と暮らしに結び付く言語研究の重要な対象です。'))],
    ['salt_boundary_history'],'livelihood','商圏を示す地名が並べば、方言の境界も同じ線で描ける？','取引の制度上の範囲と、言語の使用域は別です。どちらも独自の証拠で確かめ、同じ地域というだけで重ねません。')

    add('kasai-market-space-names','生業語彙・空間と行為','「軒端商・店借商・大道商・中座」は、売る品物の名か',
    '笠井市の三種の商いを、場所を使う関係と語の構造から読み解く。',
    '商いを分ける名前には、商品ではなく、どこを使って売るかという空間の情報が含まれます。場所の名が取引の形を示す仕組みは、生業と言葉の関係を考える具体例です。',[
    ('同じ物を売っても、商いの名前が違う場合',p('仕事の分類は、何を売るかという商品の種類だけではありません。どこに店を設け、誰の場所を使い、どんな形で物を並べるかも分類の軸になります。語の中に場所の要素があるとき、空間と行為の関係を読む必要があります。','軒端・店借・大道という形を知っていても、当時の資料で何を指すかは個別に確かめます。現在の商店や道路の利用形態から、歴史的な分類を逆算して説明しないことが大切です。')),
    ('市史の三つの分類と異称',p('浜松市史の笠井市の節は、軒端商・店借商・大道商を挙げ、民家の軒先、借りた店、道路中央という場所との関係を説明しています。大道商には中座という呼び方も併記されます。'+cite('kasai_trade_history','浜松市史二・三種の商法'))+table(['市史の名称・読み','資料で示す場所の関係'],[['軒端商（のきばあきない）','民家の軒先を使う'],['店借商（たながりあきない）','民家の店を借りる'],['大道商（だいどうあきない）','道路の中央に商品を並べる'],['中座（なかざ）','同資料で大道商の異称として併記']], '原資料に示された読みと対象を保持した表')),
    ('場所の名が、行為のまとまりを表す',p('軒端という場所の語に商いが結び付くと、単にその場所を指すのでなく、その場所を用いる売り方の区分になります。中座のような名も、文字を分解した一般的な意味ではなく、当該の説明の中で何を指すかを確認します。','このような名付けでは、場所からそこで行う行為へ指示が移っています。言語学でいう換喩を考える一例として整理できますが、実際の命名の起源まで証明したわけではありません。語がどんな関係で使われているかの分析と、いつ誰がその名を作ったかという歴史は分けます。','また、三つの名が同じ階層で整理されていても、同じ一人が別の日には別の売り方をする可能性は残ります。商法の名を、人の固定した身分や家の永続的な屋号と同じにしないことが必要です。')),
    ('異称の対応は、出典の範囲で読む',p('中座を大道商に対応させるのは、この市史の併記を根拠にしています。同じ形が他分野や他地域にあっても、すべて同じ商いを指すと拡大しません。語形と意味の対応には使用分野の条件を添えます。','市史の三分類を、現在の営業許可や道路利用の制度の分類として提示することも避けます。このノートで扱うのは、歴史資料の語がどんな空間的な違いを取り出すかという問題です。')),
    ('商品・場所・人の三つの図を分ける',p('学習では、売る商品、使う場所、商いをする人を別の札にします。同じ商品を別の場所で売る場合や、同じ人が違う売り方をする場合を想定し、どの札が変わると資料の呼称が変わるかを考えてみてください。','研究では、原表記と読み、場所の利用関係、売った物、使用時期、資料の種類を残します。仕事の語彙を空間の使い方と結び付けて記述することで、商いの名前が暮らしのどの違いを表すかが明確になります。'))],
    ['kasai_trade_history'],'livelihood','軒端商・店借商・大道商は、売る商品の三分類？','市史では売る場所や使い方による区分です。商品、場所、人の分類を混同せずに読みます。')

    add('crop-names-and-compounds','生業語彙・作物の命名','「なんばん」と「なんばんきび」は、同じ作物の別名か',
    '郡誌の唐辛子・とうもろこし・じゃがいもの記録から、複合語と対象の分類を読む。',
    '名前に同じ部分が含まれても、指す作物が同じとは限りません。語の構成、原注の漢字、記録地を合わせ、命名の観点と実際の指示対象を分けて検討します。',[
    ('名前の一部が同じでも、同じ物とは限らない',p('作物の名前には、土地、外来のイメージ、形、既知の植物との関係などが含まれることがあります。しかし、語形の共通部分から、実際にどの土地を経て来たかや、同じ種類の植物かを決めることはできません。原資料が何の対象へ対応させているかを先に確かめます。','複合語を読むときは、全体の指示対象と、各部分から連想される意味を分けます。見た目の分解が容易でも、そのまま語源の証明になるわけではありません。')),
    ('郡誌の三つの作物の対応',gunshi('なんばん','なんばんきび','こうしういも')+p('なんばんは福島村の唐辛子、なんばんきびは浦川村のとうもろこしに対応します。浦川村のこうしういもには馬鈴薯という原注があります。地域と原注を残すことで、共通する部分のある名前を、同じ作物の語形差として誤って統合せずに済みます。'+cite('gunshi','磐田郡誌・1246、1250頁'))),
    ('複合語の末尾と、資料の対象を照合する',table(['比較の層','確認する問い','この表での観察'],[['語形','どの部分が共通するか','なんばんという部分'],['全体の意味','どの作物に対応するか','唐辛子ととうもろこしは別'],['原注','対象の同定に何があるか','玉蜀黍・馬鈴薯等の漢字'],['地域','同じ話者が区別した記録か','村の異なる採録を含む']], '語の構成と指示対象を別に読む')+p('なんばんきびのような複合語では、共通する部分だけを取り出して訳すと、全体が指す対象を取り違えます。対象を示す漢字の原注は重要な手がかりですが、当時の植物の分類と現代の学術的な種・品種の分類を完全に一致させた同定結果とは限りません。','こうしういもの地名らしい部分についても、その表記から実際の伝来経路を決めません。名前の中の地理と、物の移動の歴史を区別して検証することが、語源を深く調べるための条件です。')),
    ('作物名の一覧を、伝播の地図へ直結しない',p('ある名前がその地域に記録されたことは、その作物がその名の土地から直接伝わった証拠ではありません。名前が別の地域で付いた後、物とともに広がる場合も、物が広がった後で名前が変わる場合も考えられます。複数の説明を比較するには、年代の分かる用例が必要です。','また、一つの郡誌の採録には、記録者の関心や村ごとの項目数の差があります。名が載らない場所で作物が作られなかった、知られていなかったという結論にはできません。')),
    ('語形・作物・来歴を三列で読む',p('学習では、原形、原資料での対応、来歴について分かることを別欄にしてみます。対応語の欄は埋められても、伝来の経路の欄は今回の資料だけでは空欄です。同じ部分を持つ名前を見つけたとき、何が分かり何がまだ分からないかを具体化できます。','研究では、栽培や流通の記録、古い種苗の目録、語の用例を別資料として照合します。作物の地域名を、珍しい別名の列挙ではなく、命名の構造と物の移動を分けて調べる題材へ変えられます。'))],
    ['gunshi'],'livelihood','なんばんを含む二つの語は、同じ植物名としてまとめられる？','郡誌では対応する作物が異なります。共通する語形の部分と、語全体の意味を分けて保持します。')
    return notes


def augment_existing_notes(notes,table,gunshi,cite):
    """Add overlapping evidence to its existing question rather than split thin pages."""
    by={n['slug']:n for n in notes}
    changes={}
    def add(slug,heading,text,sources=()):
        n=by[slug]; key='supplement-'+str(len(changes.get(slug,[]))+1)
        block=f'<section id="{key}"><h2>{heading}</h2>{text}</section>'
        marker='<aside class="research-exercise">'
        if marker in n['body']:n['body']=n['body'].replace(marker,block+marker,1)
        else:n['body']+=block
        for s in sources:
            if s not in n['sources']:n['sources'].append(s)
        n['updated']='2026-11-13';changes.setdefault(slug,[]).append(heading)
    add('family-position-and-life-course','婚姻の行為と、生活段階の呼び名も区別する',
        gunshi('やごめ')+'<p>やごめは袋井町のやもめに対応し、原注は寡婦です。これは出生順や、ある人から見た親族関係と同じ種類の分類ではありません。生活の中の関係が変わった状態を示す対応として読みます。この一行から、本人へ直接そう呼び掛けたことや、その人の仕事・権利まで確定することはできません。</p><p>結婚するという対応を持つ龍川村のかたるは、福島村の仲間になるという対応の同形語と、既存ノート<a href="/enshu/research/same-form/">「同じ綴り、違う意味」</a>で比較しています。関係を結ぶ行為、家族の中の位置、生活段階の状態を分ければ、婚姻に関する語を一つの制度の説明へ丸めずに読めます。</p>')
    add('childcare-and-play','子どもを指す語と、世話する仕事の名',
        gunshi('きこ')+'<p>山香村辺のきこは、小さい子どもという対応で記録されています。子どもを指す語と、子守という仕事を示すもんりい・もうやあは、同じ育児の話題に属しても指す対象が異なります。子どもという対象、その人をあやす行為、世話する役割を別にして索引を作ると、語と暮らしの関係が明確になります。</p><p>ただし、小さいという対応だけから年齢の上限を決めたり、誰がどんな口調で本人へ呼び掛けたかを補ったりはしません。子どもについて説明する語と、本人を呼ぶ語は別に確認する必要があります。</p>')
    add('tool-names-and-classification','刃物の上位語が同じでも、実物が同じとは限らない',
        gunshi('かあだ','きやま','ぼち','ちよんな')+'<p>かあだ・きやま・ぼちは、異なる記録地でなたに対応します。一方、ちよんなは手斧に対応します。同じ訳語に整理された三語を比較する際も、刃の形、用途、寸法の対応を確かめずに、完全に同じ道具の地域名だけが違うと決めません。上位語で共通することと、実物の型が一致することは別です。</p><p>逆に、道具名が違うから材質や用途も必ず違うとは限りません。実物の記録と名称の記録を対応させ、どの違いを語が取り出しているかを調べます。原表記・地域・頁を保持した表は、その比較へ戻る入口です。</p>')
    add('tool-names-and-classification','身体と道具を、運ぶ動作の中へ置く',
        gunshi('いないぼう','しよなふ','すつぽう','ちやんこう','はんこ')+'<p>いないぼうは荷い棒という物の名、しよなふは背負い込むという動作です。すつぽう・ちやんこう・はんこは袖や衣服に関わる対応を持ちます。同じ仕事の道具や装備として関係しうるものの、この一覧自体が一つの作業場面を記録したものではありません。</p><p>筒袖・袖なし・袖なし半纏という対応は、衣服の形の一部と種類の捉え方を比較する手がかりです。どの仕事着だったか、動きやすさのためにその形を選んだかは、実物や使用の記録を加えて確認します。仕事と結び付けやすい語ほど、資料にない場面を分かりやすさのために創作しないことが大切です。</p>')
    add('fukude-textile-vocabulary','原料・加工段階・担い手をさらに分ける',
        table(['市史に現れる語','区別する対象'],[['実綿・繰綿・綿布','綿を扱う段階と製品'],['賃機・十反引き','働き方と織る方法の記述'],['紺屋職・藍染・綿糸','人の職名・作業・対象となる材料']], '浜松市史の別々の節から整理した比較')+
        '<p>市史の綿布の取引の節は、実綿・繰綿・綿布の取引と仲買渡世を述べています。織物と女性の節は、賃機、技術を教える人、取引を行う人、十反を続けて織る十反引きという説明を含みます。藍染の節では、農家の依頼で綿糸を染める紺屋職が現れます。'+cite('cotton_trade_history','浜松市史二・綿布の取引')+cite('weaving_people_history','同・織物と女性')+cite('indigo_history','同・藍染')+'</p><p>これらを全部「織物の言葉」という箱に置く前に、物が加工される段階、人が担う仕事、技術の区分を分けます。一人が織り、教え、取引する場合も、三つの人名を指すわけではなく、同じ人に異なる役割が重なります。人の呼び方と職業を対応させる際は、この役割の重なりを残す必要があります。</p><p>市史の個人の来歴には伝承や別文献に基づく説明も含まれます。今回それらの原本を独立に調査したとはせず、語の構造を読むために確認した範囲を示しています。商品名だけでなく工程と担い手まで読むことで、既存の福田の織物史の説明を生業語彙の体系へつなげられます。</p>',
        ['cotton_trade_history','weaving_people_history','indigo_history'])
    add('livelihood-change-and-language','転業だけでなく、原料の流れでも仕事がつながる',
        '<p>県の浜名湖の取材記事には、かつて養鰻の餌として、繭から糸を取った後の蚕のさなぎを利用したという説明があります。'+cite('market2024','静岡県2024・浜名湖の養鰻の説明')+'</p><p>これは一人が仕事を替えるというつながりとは別に、ある仕事で生じる物が別の仕事で使われるというつながりです。担い手の移動、技術の移動、材料の移動を分けることで、産業の接点を具体的に追えます。ただし材料が動くことは、その材料の方言名や会話の習慣も同時に移ったという実証ではありません。物の経路と言葉の経路を別に記録します。</p>',
        ['market2024'])
    add('words-and-things','呼称と暮らしを、後から検証できる記録へ',
        '<p>川村（2019）は宮城県気仙沼市小々汐の日記をデータベース化する中で、表記の違い、人名と屋号、民俗の分類項目の扱いを検討しています。遠州の事例ではありませんが、原資料の情報と検索・分類のための整理を分ける比較の視点を得られます。'+cite('folk_archive2019','川村2019・資料化の過程')+'</p><p>原表記を一つの現代表記へ上書きすると、後から音の違いや書き方の違いを調べられなくなります。逆に原表記だけでは検索しにくい場合、原形を残したまま別の検索欄を作れます。家・人・仕事の関係も同じで、名前の文字列を保存するだけでなく、何を指すか、誰がいつ記したかという対応を残すことが必要です。</p><p>このサイトの郡誌の表は、原形・意味整理・原注・記録地・頁・固定IDを別欄で保持しています。これは原資料と編集上の判断を照合するための構造であり、検索用の整理を原記録の語形と取り違えないための工夫です。</p>',
        ['folk_archive2019'])
    return changes
